insert into rep_plan values('{"books":[{"book":"2A","subject_code":"REPERTOIRE_2A","subject_name":"Piano Adventures - Level 2A - Lesson Book (2nd Edition)","source_authors":"Nancy Faber và Randall Faber","source_file":"VIBE_Piano_Pre_Grade_Repertoire_2A_50_Lessons.pdf","source_sha256":"370fa0c776ba1a336ccb47f44b29d9a973865e03a0561ec609b366ff2379976f","source_context":"Trang giáo án VIBE 1\nVIBE ACADEMY · PIANO PRE GRADE · REPERTOIRE\nGiáo án 50 Lesson\ntheo Piano Adventures 2A\nPiano Adventures - Level 2A - Lesson Book\n(2nd Edition)\nNancy Faber và Randall Faber\nFaber Piano Adventures\nTên môn theo giáo trình\nRepertoire → Piano Adventures - Level 2A - Lesson Book (2nd Edition)\nVị trí theo yêu cầu: Piano → Pre Grade → môn Repertoire hiện có. Tên sách và ấn bản\nđược giữ trong dữ liệu nguồn; ID môn và lịch sử học tập cần được bảo toàn khi nhập.\nCách sử dụng\n• Phân bổ 50 Lesson gồm 4 bài ôn Level 1, 42 bài theo 7 Unit và 4 bài Challenge. Một\nLesson là đơn vị nội dung, có thể cần nhiều buổi học.\n• Tiêu đề và trang tham chiếu lấy từ sách. Mục tiêu, hoạt động, bài luyện và ghi chú do\nVIBE biên soạn. Đây không phải 50 Lesson do nhà xuất bản đánh số.\n• Tên môn đề xuất giữ đầy đủ tên sách và ấn bản. Level 2A là cấp độ riêng của Piano\nAdventures; Pre Grade là vị trí nội bộ VIBE theo yêu cầu.\n• Các bài biểu diễn, bài chuẩn bị và Challenge được giữ theo mạch sách trong môn\nRepertoire đã chỉ định.\n• Chưa nhập vào database trên máy Mac. Gói triển khai kèm theo kiểm tra đúng môn\nhiện có, bảo toàn ID và lịch sử. Nếu cùng môn đã có sách 2B hoặc sách khác, phải đối\nchiếu trước khi nhập 2A.\n\nTrang giáo án VIBE 2\nĐối chiếu nguồn và cấu trúc\nNguồn: 1) Lesson lv 2A.pdf - 68 trang scan. Đã đọc hình ảnh toàn bộ trang, đối chiếu\nProgress Chart ở PDF 4-5 và danh mục ở PDF 67. Nội dung học: trang in 4-63 = PDF\n6-65.\nCác điểm cần giữ đúng\n• Chỉ cột Lesson của Progress Chart thuộc quyển này. Các cột sách đi kèm và số CD track\nkhông được nhập thành Lesson hoặc liên kết âm thanh chưa có.\n• Trang in 18, 30, 36, 48 và 63 được dùng cho nhiều Lesson có phạm vi riêng. Từng\nLesson ghi rõ phần giới thiệu, bản nhạc hoặc nhóm mẫu tương ứng.\n• In an Old Castle: trang in 52 là Secondo của giáo viên, trang 53 là Primo của học viên.\nKhông biến phần giáo viên thành yêu cầu học viên phải học.\n• Challenge cuối sách gồm 12 mẫu năm ngón trưởng. F-sharp/G-flat là hai cách viết cùng\ncao độ. Bốn Lesson Challenge được đặt sau phần bài nhạc Unit 7, không tự tạo Unit 8.\n• Trang chứng nhận PDF 66 không phải Final Test hoặc lệnh hoàn thành cấp độ. Giáo viên\nđiều chỉnh tiến độ và dùng quy trình học vụ đã được phê duyệt.\nPhân bổ theo Unit\nMục\nTên theo sách\nLesson\nTrang in\nÔn 1\nGet Ready for Take-off! / Note Reading Guide / Review Piece\n01-04\n4-9\n1\nEighth Notes\n05-10\n10-17\n2\nTransposition\n11-16\n18-23\n3\nThe Phrase\n17-19\n24-27\n4\nHalf Steps and Whole Steps\n20-24\n28-33\n5\nThe D 5-Finger Scale\n25-31\n34-41\n6\nThe A 5-Finger Scale\n32-35\n42-47\n7\nMinor 5-Finger Scales\n36-50\n48-63\n\nTrang giáo án VIBE 3\nBảng tra Lesson 01-17\nBài\nTên bài / hoạt động\nIn\nPDF\n01\nGet Ready for Take-off! - Rhythm / Time Signatures / Reading\n4\n6\n02\nGet Ready for Take-off! - Theory / Symbols and Terms\n5\n7\n03\nNote Reading Guide - The Adventures of E-G-B Mouse\n6-7\n8-9\n04\nWhen the Saints Go Marching In\n8-9\n10-11\n05\n8th Notes / 8th Note Patterns\n10\n12\n06\nAwesome Creatures\n11\n13\n07\nB below Middle C / Skip to My Lou\n12\n14\n08\nThe Natural Sign / Leftover Popcorn\n13\n15\n09\nA Minuet for Mr. Bach''s Children\n14-15\n16-17\n10\nReview: The Damper Pedal / Mr. Brahms'' Famous Lullaby\n16-17\n18-19\n11\nIce Cream\n18\n20\n12\nMore Ice Cream\n18\n20\n13\nTransposing / Mr. Haydn''s Theme\n19\n21\n14\nMy Daydream\n20-21\n22-23\n15\nNew Dynamic Marks / The Clock Strikes Thirteen!\n22\n24\n16\nThe Elf''s Silver Hammer\n23\n25\n17\nThe Phrase / Ode to Joy\n24-25\n26-27\nCác tên ghép hoặc chia phần dùng để tổ chức dạy; tên bài gốc được giữ trong tiêu đề. Dùng trang in để\ntra sách và trang PDF để tra tệp scan.\n\nTrang giáo án VIBE 4\nBảng tra Lesson 18-34\nBài\nTên bài / hoạt động\nIn\nPDF\n18\nI Am the King\n26\n28\n19\nPhrase Warm-up / Moonlight Melody\n27\n29\n20\nHalf Steps / The Puppet Show\n28\n30\n21\nHalf Step Warm-up / Kitch-iti-kipi\n29\n31\n22\nHalf Steps and Whole Steps / Whole Step Investigation\n30\n32\n23\nOur Detective Agency\n30-31\n32-33\n24\nFermata / Storms on Saturn\n32-33\n34-35\n25\nSecret Scale Formula / The D 5-Finger Scale\n34\n36\n26\nCheers for D Chords\n35\n37\n27\nThis R.H. Old Man\n36\n38\n28\nThis L.H. Old Man\n36\n38\n29\nRhythm Warm-up / Spring\n37\n39\n30\nPirate of the North Sea\n38-39\n40-41\n31\nThe Queen''s Royal Entrance\n40-41\n42-43\n32\nThe A 5-Finger Scale / Cheers for A Chords\n42\n44\n33\nPeter Pan''s Flight\n43\n45\n34\nL.H. Boogie Warm-up / Aardvark Boogie\n44-45\n46-47\nCác tên ghép hoặc chia phần dùng để tổ chức dạy; tên bài gốc được giữ trong tiêu đề. Dùng trang in để\ntra sách và trang PDF để tra tệp scan.\n\nTrang giáo án VIBE 5\nBảng tra Lesson 35-50\nBài\nTên bài / hoạt động\nIn\nPDF\n35\nNew: Ledger Line E / Whirling Leaves\n46-47\n48-49\n36\nMajor and Minor Sounds\n48\n50\n37\nChanging Moods\n48-49\n50-51\n38\nTempo Marks / Sword Dance\n50-51\n52-53\n39\nIn an Old Castle - Primo\n52-53\n54-55\n40\nR.H. Warm-up / Jazz Blast\n54\n56\n41\nJazz Blast Improvisation\n55\n57\n42\nCheers for Cm Chords / Applause for Gm Chords\n56\n58\n43\nHooray for Dm Chords / Bravo for Am Chords\n57\n59\n44\nWhat''s a Lead Sheet?\n58\n60\n45\nLead Sheet for Go Tell Aunt Rhody\n59\n61\n46\nPyramids at Night\n60-61\n62-63\n47\nAdventure Scale and Chord Warm-Ups - C / G / F\n62\n64\n48\nAdventure Scale and Chord Warm-Ups - D / A / E\n63\n65\n49\nAdventure Scale and Chord Warm-Ups - Db / Ab / Eb\n63\n65\n50\nAdventure Scale and Chord Warm-Ups - F# / Gb / Bb / B\n63\n65\nCác tên ghép hoặc chia phần dùng để tổ chức dạy; tên bài gốc được giữ trong tiêu đề. Dùng trang in để\ntra sách và trang PDF để tra tệp scan.","lessons":[{"number":1,"code":"PIANO-PRE-REP-2A-L01","title":"Get Ready for Take-off! - Rhythm / Time Signatures / Reading","unit":0,"unit_title":"Ôn Level 1","challenge":false,"source_pdf_pages":"6","source_printed_pages":"4","syllabus_pdf_page":6,"content_scope":"Các mục Rhythm, Time Signatures và Reading của phần ôn Level 1.","learning_objectives":"Ôn trường độ, dấu lặng, số chỉ nhịp, quãng và ký hiệu đã học.","classroom_activities":"Nối nốt với dấu lặng; bổ sung vạch nhịp và phách; gõ rồi đàn mẫu trên hợp âm C/G, gọi tên các quãng và ký hiệu.","homework":"Ôn lại mẫu tiết tấu và ký hiệu còn nhầm theo ghi chú giáo viên.","teacher_notes":"Bài ôn dùng để nhận diện kiến thức cần bổ sung; không phải Final Test."},{"number":2,"code":"PIANO-PRE-REP-2A-L02","title":"Get Ready for Take-off! - Theory / Symbols and Terms","unit":0,"unit_title":"Ôn Level 1","challenge":false,"source_pdf_pages":"7","source_printed_pages":"5","syllabus_pdf_page":6,"content_scope":"Các mục Theory và Symbols and Terms của phần ôn Level 1.","learning_objectives":"Nhận diện nửa cung, âm chủ, âm át, I/V7 và thuật ngữ cơ bản.","classroom_activities":"Đánh dấu phím theo yêu cầu, tìm tonic/dominant trong mẫu C/G, đàn I/V7 rồi giải thích các ký hiệu.","homework":"Luyện chuyển I/V7 ở C và G; ôn những thuật ngữ chưa nhớ.","teacher_notes":"Kiểm tra nền Level 1 trước khi tiếp tục; không suy ra tương đương Grade của hệ thi khác."},{"number":3,"code":"PIANO-PRE-REP-2A-L03","title":"Note Reading Guide - The Adventures of E-G-B Mouse","unit":0,"unit_title":"Ôn Level 1","challenge":false,"source_pdf_pages":"8-9","source_printed_pages":"6-7","syllabus_pdf_page":7,"content_scope":"Hướng dẫn đọc nốt trên hai khuông và các Mouse Mission.","learning_objectives":"Liên hệ nốt trên dòng/khe với phím đàn; dùng nốt mốc để đọc nốt chưa quen.","classroom_activities":"Đọc và đàn các nhóm nốt treble/bass; giáo viên che tên nốt, chỉ dòng/khe hoặc nốt mốc để học viên tìm phím.","homework":"Ôn đọc nốt cả hai khóa, ưu tiên các nốt còn phải đoán bằng thế tay.","teacher_notes":"Các Mission là hoạt động của sách, không tạo thêm cấp độ hoặc bài thi."},{"number":4,"code":"PIANO-PRE-REP-2A-L04","title":"When the Saints Go Marching In","unit":0,"unit_title":"Ôn Level 1","challenge":false,"source_pdf_pages":"10-11","source_printed_pages":"8-9","syllabus_pdf_page":7,"content_scope":"Review Piece, nốt lấy đà, giai điệu và I/V7 trong mẫu G năm ngón.","learning_objectives":"Giữ nhịp khi vào câu lấy đà; đọc giai điệu và hợp âm đã học.","classroom_activities":"Xác định phách bắt đầu, đối chiếu ô cuối; tập từng câu, tìm I/V7 rồi ghép trọn bài.","homework":"Ôn điểm vào câu và kết bài, duy trì nhịp khi ghép hai tay.","teacher_notes":"Phần Teacher Duet là phần giáo viên; học viên chỉ học bản chính theo khả năng."},{"number":5,"code":"PIANO-PRE-REP-2A-L05","title":"8th Notes / 8th Note Patterns","unit":1,"unit_title":"Eighth Notes","challenge":false,"source_pdf_pages":"12","source_printed_pages":"10","syllabus_pdf_page":8,"content_scope":"Giới thiệu nốt móc đơn, ba mẫu gõ và hoạt động trên hợp âm G.","learning_objectives":"Cảm nhận hai nốt móc đơn bằng một nốt đen trong nhịp của bài.","classroom_activities":"Giáo viên làm mẫu, học viên gõ và đếm các dòng; tìm mẫu móc đơn rồi đàn trên hợp âm G.","homework":"Gõ xen kẽ nốt đen và cặp móc đơn trên một mạch phách đều.","teacher_notes":"Ưu tiên chia phách đều trước khi tăng tốc; không coi tốc độ là ngưỡng đạt tự động."},{"number":6,"code":"PIANO-PRE-REP-2A-L06","title":"Awesome Creatures","unit":1,"unit_title":"Eighth Notes","challenge":false,"source_pdf_pages":"13","source_printed_pages":"11","syllabus_pdf_page":8,"content_scope":"Toàn bài và hoạt động Discovery ở cuối trang.","learning_objectives":"Đọc tiết tấu móc đơn trong giai điệu và phối hợp hai tay.","classroom_activities":"Xác định mẫu năm ngón, gõ các nhóm tiết tấu; đàn từng câu rồi ghép, có thể hát lời khi chơi.","homework":"Ôn các nhóm móc đơn còn vấp và giữ phần đệm ổn định.","teacher_notes":"Sách ghi tên cũ của bài là Famous People; dùng tiêu đề hiện hành Awesome Creatures, không tạo bài trùng."},{"number":7,"code":"PIANO-PRE-REP-2A-L07","title":"B below Middle C / Skip to My Lou","unit":1,"unit_title":"Eighth Notes","challenge":false,"source_pdf_pages":"14","source_printed_pages":"12","syllabus_pdf_page":9,"content_scope":"Nốt B dưới Middle C cho tay phải, toàn bài và gợi ý đổi tiết tấu.","learning_objectives":"Đọc nốt B ở tay phải và chuyển ngón cái khi giai điệu mở rộng.","classroom_activities":"Tìm B từ C, ghi I/V7 dưới hợp âm tay trái; luyện chỗ chuyển vị trí rồi ghép bài.","homework":"Ôn đoạn chuyển ngón; thử một biến thể tiết tấu trong hoạt động Creative khi đã vững.","teacher_notes":"Giữ tên nốt theo bản nhạc thay vì mặc định mỗi ngón luôn ứng với một phím."},{"number":8,"code":"PIANO-PRE-REP-2A-L08","title":"The Natural Sign / Leftover Popcorn","unit":1,"unit_title":"Eighth Notes","challenge":false,"source_pdf_pages":"15","source_printed_pages":"13","syllabus_pdf_page":9,"content_scope":"Dấu bình, toàn bài và hoạt động lặp câu cuối ở các quãng tám.","learning_objectives":"Hiểu dấu bình hủy dấu thăng/giáng và đọc các chỗ đổi vị trí tay.","classroom_activities":"Tìm dấu bình, gõ mẫu móc đơn; tập chỗ dịch tới D rồi về C và nối câu.","homework":"Luyện đoạn có dấu hóa và chuyển tay; thử câu cuối ở âm vực khác theo sách.","teacher_notes":"Không bỏ dấu bình khi học viên đã thuộc giai điệu; vẫn đối chiếu ký âm."},{"number":9,"code":"PIANO-PRE-REP-2A-L09","title":"A Minuet for Mr. Bach''s Children","unit":1,"unit_title":"Eighth Notes","challenge":false,"source_pdf_pages":"16-17","source_printed_pages":"14-15","syllabus_pdf_page":10,"content_scope":"Tiết tấu minuet 3/4, toàn bài và khung giới thiệu sổ nhạc của Anna Magdalena Bach.","learning_objectives":"Giữ nhịp 3/4 và nối các nốt móc đơn chia giữa hai tay.","classroom_activities":"Đánh dấu các ô có mẫu tiết tấu mở đầu; vỗ nhịp với giáo viên rồi tập các điểm đổi tay và sắc thái.","homework":"Ôn nối tay ở các nhóm móc đơn và xử lý chậm dần cuối bài.","teacher_notes":"Giữ tên bài theo sách; khung lịch sử là nội dung giới thiệu, không tạo một Lesson kỹ thuật riêng."},{"number":10,"code":"PIANO-PRE-REP-2A-L10","title":"Review: The Damper Pedal / Mr. Brahms'' Famous Lullaby","unit":1,"unit_title":"Eighth Notes","challenge":false,"source_pdf_pages":"18-19","source_printed_pages":"16-17","syllabus_pdf_page":10,"content_scope":"Ôn pedal, toàn bài ru và gợi ý xác định phách bắt đầu.","learning_objectives":"Đọc câu nhạc nhẹ, nhận diện lấy đà và dùng pedal tại kết bài.","classroom_activities":"Ôn ký hiệu pedal, tập từng câu với tiếng đàn êm; luyện đưa tay tới high F và nghe âm ngân ở kết.","homework":"Ôn chỗ đổi vị trí và đoạn kết với đúng ký hiệu pedal.","teacher_notes":"Không giữ pedal suốt bài này; chỉ theo ký hiệu in. Điều chỉnh ghế và hỗ trợ chân nếu cần."},{"number":11,"code":"PIANO-PRE-REP-2A-L11","title":"Ice Cream","unit":2,"unit_title":"Transposition","challenge":false,"source_pdf_pages":"20","source_printed_pages":"18","syllabus_pdf_page":11,"content_scope":"Chỉ bài Ice Cream ở nửa trên trang, dùng mẫu C năm ngón.","learning_objectives":"Chơi giai điệu trong mẫu C và nhận ra hướng đi/quãng của giai điệu.","classroom_activities":"Đọc giai điệu, gõ tiết tấu rồi ghép hai tay; mô tả những đoạn đi liền bậc để chuẩn bị chuyển giọng.","homework":"Ôn Ice Cream ở C với nhịp đều, chú ý cấu trúc câu.","teacher_notes":"Chung trang với More Ice Cream nhưng là bản ở vị trí C; phạm vi bài sau là bản ở G."},{"number":12,"code":"PIANO-PRE-REP-2A-L12","title":"More Ice Cream","unit":2,"unit_title":"Transposition","challenge":false,"source_pdf_pages":"20","source_printed_pages":"18","syllabus_pdf_page":11,"content_scope":"Chỉ bài More Ice Cream ở nửa dưới trang và câu hỏi chuyển giọng.","learning_objectives":"Nhận ra giai điệu quen khi chuyển từ mẫu C sang G.","classroom_activities":"So sánh hai bản trên trang: tên nốt đổi nhưng quan hệ quãng được giữ; đàn bản G rồi luân phiên với bản C.","homework":"Ôn hai vị trí C/G; nói điểm giống về tiết tấu và quãng.","teacher_notes":"Giáo viên có thể làm mẫu thêm một giọng theo sách; không yêu cầu tự chơi mọi giọng ngay."},{"number":13,"code":"PIANO-PRE-REP-2A-L13","title":"Transposing / Mr. Haydn''s Theme","unit":2,"unit_title":"Transposition","challenge":false,"source_pdf_pages":"21","source_printed_pages":"19","syllabus_pdf_page":12,"content_scope":"Khái niệm chuyển giọng, toàn bài trong G và chuyển sang C.","learning_objectives":"Dùng quãng để chuyển giai điệu giữa hai mẫu năm ngón.","classroom_activities":"Tập bản G, tìm và ghi I/V7; giữ cùng tiết tấu và khoảng cách khi thử bản C.","homework":"Ôn điểm còn nhầm khi chuyển giọng, kiểm tra lại bằng tai.","teacher_notes":"Đây là bản chuyển soạn chủ đề của Haydn trong sách; không thêm nguyên tác ngoài tài liệu."},{"number":14,"code":"PIANO-PRE-REP-2A-L14","title":"My Daydream","unit":2,"unit_title":"Transposition","challenge":false,"source_pdf_pages":"22-23","source_printed_pages":"20-21","syllabus_pdf_page":12,"content_scope":"Warm-up chuyển động cổ tay, toàn bài và gợi ý chuyển sang C.","learning_objectives":"Tạo câu legato, cổ tay linh hoạt và đọc chỉ dẫn quãng tám.","classroom_activities":"Luyện mẫu ngón trên nắp đàn, thử chuyển động cổ tay theo giáo viên; đàn bài ở G và chuẩn bị phần hai tay cao hơn một quãng tám.","homework":"Ôn nối câu và chuyển âm vực; thử bản C khi bản G đã ổn.","teacher_notes":"Vòng cổ tay là lựa chọn theo hướng dẫn, không ép biên độ chuyển động lớn."},{"number":15,"code":"PIANO-PRE-REP-2A-L15","title":"New Dynamic Marks / The Clock Strikes Thirteen!","unit":2,"unit_title":"Transposition","challenge":false,"source_pdf_pages":"24","source_printed_pages":"22","syllabus_pdf_page":13,"content_scope":"Crescendo, diminuendo, toàn bài và 13 tiếng chuông.","learning_objectives":"Phân biệt tăng/giảm âm lượng dần và thể hiện trên mẫu âm chuông.","classroom_activities":"Tìm tên hai dấu sắc thái; đàn các câu và 13 tiếng chuông trên high G, nghe sự tăng rồi giảm âm.","homework":"Luyện một đường tăng/giảm âm lượng liền mạch, kết hợp nhịp đều.","teacher_notes":"Sách yêu cầu giữ damper pedal suốt bài này; không áp dụng cách dùng đó cho mọi bài khác."},{"number":16,"code":"PIANO-PRE-REP-2A-L16","title":"The Elf''s Silver Hammer","unit":2,"unit_title":"Transposition","challenge":false,"source_pdf_pages":"25","source_printed_pages":"23","syllabus_pdf_page":13,"content_scope":"Toàn bài, hai tay ở khóa Sol và chuyển giọng sang G.","learning_objectives":"Đọc hai tay cùng khóa Sol, phân biệt âm vực và thể hiện sắc thái.","classroom_activities":"Xác định mẫu năm ngón, tập từng câu với dấu nhấn; chuẩn bị chuyển lên quãng tám và hai quãng tám ở cuối.","homework":"Ôn kết bài và thử chuyển sang mẫu G nếu giáo viên thấy phù hợp.","teacher_notes":"Không đọc tay trái theo khóa Fa do thói quen; kiểm tra khóa trước khi đàn."},{"number":17,"code":"PIANO-PRE-REP-2A-L17","title":"The Phrase / Ode to Joy","unit":3,"unit_title":"The Phrase","challenge":false,"source_pdf_pages":"26-27","source_printed_pages":"24-25","syllabus_pdf_page":14,"content_scope":"Khái niệm câu nhạc, Shaping the Phrase và toàn bản chuyển soạn Ode to Joy.","learning_objectives":"Nhận diện câu nhạc qua dấu luyến và tạo đường nét tăng/giảm âm lượng.","classroom_activities":"Đọc từng câu, dùng sắc thái gợi ý trong sách để tạo hướng đi; tập các chỗ chuyển tay rồi ghép.","homework":"Ôn hai câu tương phản, giữ mắt theo bản nhạc khi chơi các đoạn đã quen.","teacher_notes":"Các đường màu hướng dẫn tạo câu, không phải tiêu chí điểm số hay số lần thi."},{"number":18,"code":"PIANO-PRE-REP-2A-L18","title":"I Am the King","unit":3,"unit_title":"The Phrase","challenge":false,"source_pdf_pages":"28","source_printed_pages":"26","syllabus_pdf_page":14,"content_scope":"Toàn bài, bổ sung dấu câu và gợi ý sáng tạo tay trái.","learning_objectives":"Nhận ra ranh giới câu nhạc và cân bằng giai điệu giữa hai tay.","classroom_activities":"Dùng đường chấm để vẽ dấu câu; đàn từng đoạn rồi nối, thử đổi giai điệu tay trái ở ô 7-12 theo nhóm nốt sách gợi ý.","homework":"Ôn điểm đổi vai hai tay và giữ tính chất mạnh mẽ của bài.","teacher_notes":"Phần sáng tạo giữ tiết tấu mẫu và được giáo viên hướng dẫn; không tự thêm một bài thi sáng tác."},{"number":19,"code":"PIANO-PRE-REP-2A-L19","title":"Phrase Warm-up / Moonlight Melody","unit":3,"unit_title":"The Phrase","challenge":false,"source_pdf_pages":"29","source_printed_pages":"27","syllabus_pdf_page":15,"content_scope":"Khởi động theo dấu câu, toàn bài và câu hỏi về giai điệu tay trái.","learning_objectives":"Nối câu nhẹ và nhận ra khi giai điệu chuyển sang tay trái.","classroom_activities":"Theo đường dấu câu, tập các đoạn đổi tay; chỉ ra hai dòng có giai điệu tay trái và cân bằng tay còn lại.","homework":"Ôn từng điểm nối câu, luyện chuyển tay trái qua phải ở kết bài.","teacher_notes":"Giữ cổ tay mềm khi chuyển tay; ưu tiên tiếng giai điệu rõ thay vì hai tay cùng lớn."},{"number":20,"code":"PIANO-PRE-REP-2A-L20","title":"Half Steps / The Puppet Show","unit":4,"unit_title":"Half Steps and Whole Steps","challenge":false,"source_pdf_pages":"30","source_printed_pages":"28","syllabus_pdf_page":15,"content_scope":"Ôn nửa cung và toàn bài The Puppet Show.","learning_objectives":"Tìm hai phím kề nhau và đọc các chuyển động nửa cung trong bài.","classroom_activities":"Tìm nửa cung trên phím trắng/đen, vừa đàn vừa gọi tên khoảng cách; học bài theo câu với tay thả lỏng.","homework":"Ôn các cặp nốt nửa cung và bài chính ở tốc độ phù hợp.","teacher_notes":"Hoạt động nhắm mắt chỉ thử khi học viên đã định vị an toàn và giáo viên thấy phù hợp."},{"number":21,"code":"PIANO-PRE-REP-2A-L21","title":"Half Step Warm-up / Kitch-iti-kipi","unit":4,"unit_title":"Half Steps and Whole Steps","challenge":false,"source_pdf_pages":"31","source_printed_pages":"29","syllabus_pdf_page":16,"content_scope":"Khởi động nửa cung, toàn bài và chuyển thế tay năm ngón.","learning_objectives":"Cảm nhận chuyển động nửa cung, mở thế tay và phối hợp hợp âm.","classroom_activities":"Quan sát giáo viên làm mẫu ô 1-4, chơi cùng rồi tự chơi; luyện chuyển thế tay và các hợp âm với cổ tay mềm.","homework":"Ôn đoạn mở thế tay và các hợp âm cuối bài, giữ nhịp khi thay đổi.","teacher_notes":"Không ép độ giãn tay; dịch chuyển cánh tay để tới vị trí thuận lợi."},{"number":22,"code":"PIANO-PRE-REP-2A-L22","title":"Half Steps and Whole Steps / Whole Step Investigation","unit":4,"unit_title":"Half Steps and Whole Steps","challenge":false,"source_pdf_pages":"32","source_printed_pages":"30","syllabus_pdf_page":16,"content_scope":"Chỉ phần định nghĩa và hình bàn phím phía trên trang 30.","learning_objectives":"Phân biệt một cung với nửa cung bằng phím xen giữa.","classroom_activities":"Đánh dấu phím tạo một cung trong các hình, kiểm tra trên đàn và đối chiếu với nửa cung đã học.","homework":"Tìm một cung từ vài phím giáo viên chọn và giải thích cách tìm.","teacher_notes":"Phần bản nhạc Our Detective Agency trên cùng trang thuộc Lesson kế tiếp."},{"number":23,"code":"PIANO-PRE-REP-2A-L23","title":"Our Detective Agency","unit":4,"unit_title":"Half Steps and Whole Steps","challenge":false,"source_pdf_pages":"32-33","source_printed_pages":"30-31","syllabus_pdf_page":17,"content_scope":"Chỉ bản nhạc và hoạt động Creative; phần giới thiệu một cung đã học ở Lesson trước.","learning_objectives":"Đọc chuyển động một cung và tạo tính chất bí ẩn của giai điệu.","classroom_activities":"Tập từng câu với dấu hóa, giữ nhịp khi đổi tay; sau đó thử dãy một cung từ Middle C với pedal theo gợi ý.","homework":"Ôn các chỗ đổi dấu hóa và nghe khoảng cách một cung.","teacher_notes":"Hai Lesson cùng dẫn trang 30 nhưng khác phạm vi; không nhập thành hai bản sao của cùng bài."},{"number":24,"code":"PIANO-PRE-REP-2A-L24","title":"Fermata / Storms on Saturn","unit":4,"unit_title":"Half Steps and Whole Steps","challenge":false,"source_pdf_pages":"34-35","source_printed_pages":"32-33","syllabus_pdf_page":17,"content_scope":"Fermata, thế tay toàn cung và toàn bài.","learning_objectives":"Giữ nốt có fermata, nhận diện câu lặp và thể hiện tương phản sắc thái.","classroom_activities":"Chuẩn bị thế tay, tìm bốn lần xuất hiện câu đầu; đàn với các mức âm lượng rồi nối toàn bài và nghe pedal.","homework":"Ôn chỗ chuyển tay, các câu tương phản và kết bài nhẹ.","teacher_notes":"Sách yêu cầu giữ pedal suốt bài; fermata do giáo viên hướng dẫn, không tự đặt số phách cố định."},{"number":25,"code":"PIANO-PRE-REP-2A-L25","title":"Secret Scale Formula / The D 5-Finger Scale","unit":5,"unit_title":"The D 5-Finger Scale","challenge":false,"source_pdf_pages":"36","source_printed_pages":"34","syllabus_pdf_page":18,"content_scope":"Công thức mẫu năm ngón trưởng, ôn C/G và mẫu D với I/V7.","learning_objectives":"Tìm mẫu D bằng thứ tự một cung - một cung - nửa cung - một cung.","classroom_activities":"Đối chiếu C/G, tìm F-sharp trong D; đàn hai tay theo từng mẫu và chuyển I/V7.","homework":"Ôn mẫu D cùng dấu thăng, gọi tên phím đen và ngón sử dụng.","teacher_notes":"Đây là mẫu năm ngón; không mở rộng thành gam một quãng tám ngoài phần sách."},{"number":26,"code":"PIANO-PRE-REP-2A-L26","title":"Cheers for D Chords","unit":5,"unit_title":"The D 5-Finger Scale","challenge":false,"source_pdf_pages":"37","source_printed_pages":"35","syllabus_pdf_page":18,"content_scope":"Hợp âm chặn/rải D, chuyển sang C và lặp lại phần D.","learning_objectives":"Phân biệt hợp âm chặn với hợp âm rải và chuyển tay qua nhau.","classroom_activities":"Tập chậm các nhóm hợp âm, chuẩn bị tay trái vắt qua; luyện chuyển D-C rồi quay lại D theo chỉ dẫn.","homework":"Ôn từng lần chuyển tay và giữ tiếng đàn đều trong phần hợp âm rải.","teacher_notes":"Kiểm tra tư thế thả lỏng, tránh giữ nguyên bàn tay căng trong lúc đổi vị trí."},{"number":27,"code":"PIANO-PRE-REP-2A-L27","title":"This R.H. Old Man","unit":5,"unit_title":"The D 5-Finger Scale","challenge":false,"source_pdf_pages":"38","source_printed_pages":"36","syllabus_pdf_page":19,"content_scope":"Chỉ bài This R.H. Old Man ở nửa trên trang 36.","learning_objectives":"Chơi giai điệu tay phải trong mẫu D, phối hợp hợp âm và đổi tay theo ký hiệu.","classroom_activities":"Đọc bản trên, tập từng câu và chỗ vắt tay trái; ghép với mạch nhịp rõ.","homework":"Ôn câu có chuyển tay và các nốt F-sharp.","teacher_notes":"Bản This L.H. Old Man là bài riêng bên dưới, được phân bổ ở Lesson tiếp theo."},{"number":28,"code":"PIANO-PRE-REP-2A-L28","title":"This L.H. Old Man","unit":5,"unit_title":"The D 5-Finger Scale","challenge":false,"source_pdf_pages":"38","source_printed_pages":"36","syllabus_pdf_page":19,"content_scope":"Chỉ bài This L.H. Old Man ở nửa dưới trang và gợi ý chuyển giọng.","learning_objectives":"Đưa giai điệu sang tay trái và cân bằng hợp âm tay phải.","classroom_activities":"So sánh vai hai tay với bài trước; giáo viên hướng dẫn vắt tay ở ô 3 rồi ghép toàn bài.","homework":"Ôn giai điệu tay trái; thử C hoặc G khi bản D đã ổn.","teacher_notes":"Giữ phân biệt hai bản cùng trang, không coi đây là bản sao của Lesson trước."},{"number":29,"code":"PIANO-PRE-REP-2A-L29","title":"Rhythm Warm-up / Spring","unit":5,"unit_title":"The D 5-Finger Scale","challenge":false,"source_pdf_pages":"39","source_printed_pages":"37","syllabus_pdf_page":20,"content_scope":"Khởi động tiết tấu và bản chuyển soạn Spring từ The Four Seasons.","learning_objectives":"Giữ nhịp 4/4 với nhóm móc đơn và thể hiện tính chất sáng của bài.","classroom_activities":"Gõ/đếm theo khởi động, tập giai điệu và chỗ echo; ghép hai tay với sắc thái.","homework":"Ôn các nhóm tiết tấu và câu đáp nhẹ, giữ phách đều.","teacher_notes":"Dùng bản chuyển soạn trong sách; Teacher Duet do giáo viên đảm nhiệm."},{"number":30,"code":"PIANO-PRE-REP-2A-L30","title":"Pirate of the North Sea","unit":5,"unit_title":"The D 5-Finger Scale","challenge":false,"source_pdf_pages":"40-41","source_printed_pages":"38-39","syllabus_pdf_page":20,"content_scope":"Toàn bài, fermata và chuyển giọng sang C.","learning_objectives":"Chơi hợp âm có độ bật nhẹ, giữ nhịp mạnh và xử lý fermata.","classroom_activities":"Tập hợp âm với cánh tay thả lỏng, học giai điệu theo câu; tìm fermata tay trái và nối bài.","homework":"Ôn các lần đổi câu; thử chuyển sang C theo gợi ý khi đã vững.","teacher_notes":"Sắc thái mạnh không đồng nghĩa đập phím; quan sát độ thả lỏng khi chơi hợp âm."},{"number":31,"code":"PIANO-PRE-REP-2A-L31","title":"The Queen''s Royal Entrance","unit":5,"unit_title":"The D 5-Finger Scale","challenge":false,"source_pdf_pages":"42-43","source_printed_pages":"40-41","syllabus_pdf_page":21,"content_scope":"Toàn bài với chuyển hợp âm D/C và gợi ý sáng tạo.","learning_objectives":"Chuyển giữa hợp âm D và C trong tính chất hành khúc.","classroom_activities":"Chuẩn bị hai hợp âm bằng từng tay, tập chỗ dịch chuyển; ghép bài và theo đúng các chỉ dẫn cuối câu.","homework":"Ôn chuyển D-C; thử một câu ngắn dùng hai hợp âm theo gợi ý sách.","teacher_notes":"Giữ phần sáng tạo như lựa chọn mở rộng sau bản chính, không thay thế nội dung nguồn."},{"number":32,"code":"PIANO-PRE-REP-2A-L32","title":"The A 5-Finger Scale / Cheers for A Chords","unit":6,"unit_title":"The A 5-Finger Scale","challenge":false,"source_pdf_pages":"44","source_printed_pages":"42","syllabus_pdf_page":21,"content_scope":"Mẫu A năm ngón với I/V7 và toàn bài hợp âm A.","learning_objectives":"Tìm C-sharp trong mẫu A và chơi hợp âm chặn/rải.","classroom_activities":"Dùng công thức cung/nửa cung để tìm mẫu A; tập từng tay, ghép bài Cheers và thử mở rộng sang G theo sách.","homework":"Ôn C-sharp, chuyển tay và sự đều tiếng ở hợp âm rải.","teacher_notes":"Giữ đúng âm trưởng; không bỏ dấu thăng do quen mẫu phím trắng."},{"number":33,"code":"PIANO-PRE-REP-2A-L33","title":"Peter Pan''s Flight","unit":6,"unit_title":"The A 5-Finger Scale","challenge":false,"source_pdf_pages":"45","source_printed_pages":"43","syllabus_pdf_page":22,"content_scope":"Toàn bài, sắc thái và chuyển lên hai quãng tám ở kết.","learning_objectives":"Tạo câu bay nhẹ trong mẫu A và thực hiện đầy đủ dấu sắc thái.","classroom_activities":"Khoanh dấu sắc thái, tập từng câu; chuẩn bị nhấc tay/chuyển vị trí và xử lý phần cao ở cuối.","homework":"Ôn đoạn cuối, nghe giảm tốc và độ nhẹ của kết bài.","teacher_notes":"Kiểm tra chỉ dẫn 15ma trước khi đàn; không nhầm với chỉ lên một quãng tám."},{"number":34,"code":"PIANO-PRE-REP-2A-L34","title":"L.H. Boogie Warm-up / Aardvark Boogie","unit":6,"unit_title":"The A 5-Finger Scale","challenge":false,"source_pdf_pages":"46-47","source_printed_pages":"44-45","syllabus_pdf_page":22,"content_scope":"Mẫu boogie tay trái, toàn bài và lựa chọn tay trái thấp hơn quãng tám.","learning_objectives":"Giữ mẫu đệm boogie đều khi giai điệu tay phải thay đổi.","classroom_activities":"Luyện riêng mẫu tay trái ô 1-2, cảm nhận nửa cung giữa ngón 3-2; ghép từng câu và tập mẫu mới ở phần sau.","homework":"Ôn mẫu đệm cùng đoạn thay đổi, tránh tăng tốc khi ghép tay.","teacher_notes":"Chuyển tay trái thấp một quãng tám là hoạt động Discovery; giữ rõ âm vực bản chính trước."},{"number":35,"code":"PIANO-PRE-REP-2A-L35","title":"New: Ledger Line E / Whirling Leaves","unit":6,"unit_title":"The A 5-Finger Scale","challenge":false,"source_pdf_pages":"48-49","source_printed_pages":"46-47","syllabus_pdf_page":23,"content_scope":"Nốt E dòng kẻ phụ, toàn bài và gợi ý biến đổi sang phím trắng.","learning_objectives":"Đọc nốt E trên khuông khóa Fa và giữ mẫu chuyển động luân phiên.","classroom_activities":"Liên hệ C-D-E dòng kẻ phụ, gọi tên rồi đàn; học từng câu, xử lý kết bài cao hai quãng tám.","homework":"Ôn đọc E và nối câu; thử biến thể tay trái A-C-E theo hướng dẫn khi sẵn sàng.","teacher_notes":"Biến thể Creative dùng các nốt được sách chỉ định; không thay dữ liệu bài chính bằng phiên bản mới."},{"number":36,"code":"PIANO-PRE-REP-2A-L36","title":"Major and Minor Sounds","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":false,"source_pdf_pages":"50","source_printed_pages":"48","syllabus_pdf_page":23,"content_scope":"Chỉ phần khái niệm trưởng/thứ phía trên trang 48.","learning_objectives":"Nghe và tìm sự khác nhau khi hạ nốt thứ ba của mẫu trưởng nửa cung.","classroom_activities":"Chơi C trưởng, hạ nốt thứ ba rồi nghe C thứ; gọi tên công thức một cung/nửa cung của hai mẫu.","homework":"Luân phiên C trưởng/C thứ và nói nốt nào thay đổi.","teacher_notes":"Bài Changing Moods bắt đầu phía dưới trang này, thuộc Lesson tiếp theo."},{"number":37,"code":"PIANO-PRE-REP-2A-L37","title":"Changing Moods","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":false,"source_pdf_pages":"50-51","source_printed_pages":"48-49","syllabus_pdf_page":24,"content_scope":"Các mẫu C/Cm, G/Gm, D/Dm, A/Am và hợp âm đi kèm.","learning_objectives":"Phân biệt bốn cặp mẫu năm ngón trưởng/thứ bằng nhìn, nghe và cảm giác tay.","classroom_activities":"Học từng cặp, gọi tên dấu hóa và chơi hợp âm kết; so sánh nốt thứ ba giữa hai dạng.","homework":"Ôn cặp còn nhầm, ghi lại thay đổi ở nốt thứ ba.","teacher_notes":"Không lấy những Achievement Skill Sheets được dẫn chiếu ngoài sách làm nội dung bắt buộc khi chưa có tài liệu."},{"number":38,"code":"PIANO-PRE-REP-2A-L38","title":"Tempo Marks / Sword Dance","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":false,"source_pdf_pages":"52-53","source_printed_pages":"50-51","syllabus_pdf_page":24,"content_scope":"Allegro, Moderato, Andante và toàn bài Sword Dance.","learning_objectives":"Hiểu tính chất các tốc độ cơ bản và chơi bài ở mẫu năm ngón thứ.","classroom_activities":"Đọc ba thuật ngữ, tập từng câu và chỗ dịch tay nhanh; thử các tốc độ theo giáo viên, giữ giai điệu rõ.","homework":"Ôn chỗ chuyển vị trí và đoạn trở lại đầu giai điệu.","teacher_notes":"Khoảng metronome in trong phần thuật ngữ là tham khảo; không biến thành ngưỡng thi hoặc bắt trẻ tăng tốc quá sớm."},{"number":39,"code":"PIANO-PRE-REP-2A-L39","title":"In an Old Castle - Primo","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":false,"source_pdf_pages":"54-55","source_printed_pages":"52-53","syllabus_pdf_page":25,"content_scope":"Primo dành cho học viên ở trang 53; Secondo trang 52 là phần giáo viên để phối hợp duet.","learning_objectives":"Giữ giai điệu ở hai tay chuyển động song song và nghe bạn đàn trong duet.","classroom_activities":"Học Primo riêng với hai tay cao hơn một quãng tám, sau đó ghép giáo viên chơi Secondo; thử chuyển sang D minor theo gợi ý.","homework":"Ôn Primo với nhịp Andante đều, luyện các câu chưa liền.","teacher_notes":"Không giao Secondo như bài bắt buộc của học viên; hai trang cùng tham chiếu để giáo viên chuẩn bị duet."},{"number":40,"code":"PIANO-PRE-REP-2A-L40","title":"R.H. Warm-up / Jazz Blast","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":false,"source_pdf_pages":"56","source_printed_pages":"54","syllabus_pdf_page":25,"content_scope":"Khởi động tay phải, toàn bài và nhận diện hợp âm C minor.","learning_objectives":"Chuyển ngón tay phải qua nhau và phối hợp các bước nhảy trong mẫu C minor.","classroom_activities":"Làm theo warm-up của giáo viên, tập chậm điểm đổi vị trí; ghép bài rồi tìm hợp âm C minor.","homework":"Ôn chỗ chuyển ngón và nhảy tay; giữ nhịp khi đổi sắc thái.","teacher_notes":"Tiêu đề phụ mô tả tính chất nhanh, nhưng giáo viên chọn tốc độ phù hợp trước khi tăng dần."},{"number":41,"code":"PIANO-PRE-REP-2A-L41","title":"Jazz Blast Improvisation","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":false,"source_pdf_pages":"57","source_printed_pages":"55","syllabus_pdf_page":26,"content_scope":"Hướng dẫn ứng tấu và Teacher Duet đi kèm.","learning_objectives":"Ứng tấu bằng mẫu C minor mở rộng tới B-flat và trở về bài chính theo tín hiệu.","classroom_activities":"Chơi nhóm nốt được cho, nghe giáo viên đệm rồi tạo câu bằng nốt lặp/bước đi/quãng nhảy; trở lại Jazz Blast khi được báo.","homework":"Thử một câu ngắn với nhóm nốt của sách và duy trì phách đều.","teacher_notes":"Teacher Duet thuộc giáo viên; không yêu cầu học viên đọc toàn bộ phần đệm để được ứng tấu."},{"number":42,"code":"PIANO-PRE-REP-2A-L42","title":"Cheers for Cm Chords / Applause for Gm Chords","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":false,"source_pdf_pages":"58","source_printed_pages":"56","syllabus_pdf_page":26,"content_scope":"Hai bài hợp âm Cm và Gm, dạng chặn/rải và kết ở âm trầm.","learning_objectives":"Nhận diện chữ m và chơi hợp âm thứ ở C/G với chuyển tay.","classroom_activities":"So sánh hai mẫu, đàn chặn rồi rải theo ký hiệu; tập đặt tay vào nốt trầm cuối mỗi bài.","homework":"Ôn một chuỗi Cm và một chuỗi Gm, gọi tên nốt thứ ba.","teacher_notes":"Giữ ngón tay thoải mái khi tới âm trầm; đọc số ngón và gợi ý hỗ trợ ngón trong sách."},{"number":43,"code":"PIANO-PRE-REP-2A-L43","title":"Hooray for Dm Chords / Bravo for Am Chords","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":false,"source_pdf_pages":"59","source_printed_pages":"57","syllabus_pdf_page":27,"content_scope":"Hai bài Dm/Am và gợi ý tạo bài luyện hợp âm.","learning_objectives":"Chơi hợp âm thứ D/A và chuyển từ dạng chặn sang rải.","classroom_activities":"Đọc từng mẫu, luyện chuyển tay và kết âm trầm; chọn một hợp âm để tự tạo bài luyện ngắn theo gợi ý.","homework":"Ôn Dm/Am và so sánh với D/A trưởng đã học.","teacher_notes":"Hoạt động tự tạo bài luyện là lựa chọn mở rộng, không thêm một chương trình hay môn học."},{"number":44,"code":"PIANO-PRE-REP-2A-L44","title":"What''s a Lead Sheet?","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":false,"source_pdf_pages":"60","source_printed_pages":"58","syllabus_pdf_page":27,"content_scope":"Khái niệm lead sheet, ký hiệu hợp âm và chuẩn bị G/Gm/D.","learning_objectives":"Hiểu bản giai điệu kèm ký hiệu hợp âm, phân biệt ký hiệu trưởng/thứ.","classroom_activities":"Giải thích cấu trúc lead sheet; đàn G, Gm, D và luyện chuyển để chuẩn bị bài ở trang tiếp theo.","homework":"Ôn đọc ba ký hiệu và chuyển hợp âm theo thứ tự giáo viên giao.","teacher_notes":"Sách hướng dẫn đệm hợp âm chặn vào phách 1 mỗi ô; chưa yêu cầu tự thêm kiểu đệm phức tạp."},{"number":45,"code":"PIANO-PRE-REP-2A-L45","title":"Lead Sheet for Go Tell Aunt Rhody","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":false,"source_pdf_pages":"61","source_printed_pages":"59","syllabus_pdf_page":28,"content_scope":"Lead sheet ở G major/G minor và gợi ý chuyển sang C.","learning_objectives":"Đọc giai điệu và tự ghép hợp âm từ ký hiệu trên khuông.","classroom_activities":"Tập giai điệu đến khi ổn, thêm hợp âm chặn tay trái ở phách 1; nghe sự đổi màu G sang Gm.","homework":"Ôn điểm đổi hợp âm; thử bản C với các hợp âm gợi ý nếu sẵn sàng.","teacher_notes":"Giữ phần học viên là lead sheet; phần Teacher Duet bên dưới không phải bản đệm bắt buộc phải chép lại."},{"number":46,"code":"PIANO-PRE-REP-2A-L46","title":"Pyramids at Night","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":false,"source_pdf_pages":"62-63","source_printed_pages":"60-61","syllabus_pdf_page":28,"content_scope":"Toàn bài trong G minor, C-sharp tạo hiệu ứng và cấu trúc chuyển âm vực.","learning_objectives":"Đọc mẫu G minor có dấu hóa bổ sung, nối các câu ở nhiều âm vực.","classroom_activities":"Xác định C-sharp, luyện mẫu mở đầu lặp ba lần; tập arpeggio và các chuyển tay/âm vực rồi ghép với sắc thái.","homework":"Ôn hai điểm chuyển âm vực và mẫu tiết tấu Discovery cuối trang.","teacher_notes":"Sách ghi tên cũ là Snake Charmer; dùng Pyramids at Night làm tên bài, không tạo bản trùng."},{"number":47,"code":"PIANO-PRE-REP-2A-L47","title":"Adventure Scale and Chord Warm-Ups - C / G / F","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":true,"source_pdf_pages":"64","source_printed_pages":"62","syllabus_pdf_page":29,"content_scope":"Challenge Section: Adventure Warm-up in C và nhóm mẫu C/G/F.","learning_objectives":"Vận dụng mẫu khởi động cho các mẫu năm ngón trưởng có hợp âm toàn phím trắng.","classroom_activities":"Học mẫu C với hợp âm I/V7 rồi thử G/F bằng sơ đồ phím; khoanh nhóm đã học theo gợi ý sách.","homework":"Ôn nhóm giáo viên đã chọn, giữ số ngón và hợp âm rõ.","teacher_notes":"Challenge có thể giới thiệu dần trong Level 2A; không bắt buộc học hết mọi giọng trong một buổi."},{"number":48,"code":"PIANO-PRE-REP-2A-L48","title":"Adventure Scale and Chord Warm-Ups - D / A / E","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":true,"source_pdf_pages":"65","source_printed_pages":"63","syllabus_pdf_page":29,"content_scope":"Challenge Section: hàng trên trang 63, nhóm hợp âm trắng-đen-trắng.","learning_objectives":"Tìm D/A/E năm ngón và nhận ra hình thế hợp âm chung.","classroom_activities":"Đối chiếu sơ đồ, gọi tên phím đen rồi áp dụng mẫu Adventure Warm-up ở trang trước.","homework":"Ôn một hoặc hai giọng được giao; luyện chuyển từ mẫu sang hợp âm.","teacher_notes":"Phần này là nhóm đầu trên cùng trang 63; không lặp nội dung hai nhóm bên dưới."},{"number":49,"code":"PIANO-PRE-REP-2A-L49","title":"Adventure Scale and Chord Warm-Ups - Db / Ab / Eb","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":true,"source_pdf_pages":"65","source_printed_pages":"63","syllabus_pdf_page":30,"content_scope":"Challenge Section: hàng giữa trang 63, nhóm hợp âm đen-trắng-đen.","learning_objectives":"Đọc ba mẫu năm ngón có dấu giáng và định vị hợp âm tương ứng.","classroom_activities":"Tìm phím theo từng sơ đồ, so sánh nhóm hợp âm; chơi mẫu khởi động khi thế tay đã thoải mái.","homework":"Ôn giọng được giáo viên chọn, gọi tên nốt trước khi chơi.","teacher_notes":"Giữ đúng tên ký âm Db/Ab/Eb trên sách; không đổi toàn bộ sang tên dấu thăng cho thuận tay."},{"number":50,"code":"PIANO-PRE-REP-2A-L50","title":"Adventure Scale and Chord Warm-Ups - F# / Gb / Bb / B","unit":7,"unit_title":"Minor 5-Finger Scales","challenge":true,"source_pdf_pages":"65","source_printed_pages":"63","syllabus_pdf_page":30,"content_scope":"Challenge Section: nhóm cuối trang 63; F# và Gb là hai cách viết của cùng cao độ trên đàn.","learning_objectives":"Nhận diện các hình thế còn lại và đọc hai cách gọi F-sharp/G-flat.","classroom_activities":"Đối chiếu các sơ đồ F#/Gb, Bb, B; vẽ mô hình phím trắng/đen theo Discovery rồi chơi mẫu được giao.","homework":"Ôn nhóm còn khó và đối chiếu lại dấu hóa với sơ đồ.","teacher_notes":"Tổng bộ Challenge có 12 cao độ âm chủ trưởng; F#/Gb không được đếm thành hai giọng độc lập. Đây vẫn là mẫu năm ngón."}]},{"book":"2B","subject_code":"REPERTOIRE_2B","subject_name":"Piano Adventures - Level 2B - Lesson Book (2nd Edition)","source_authors":"Nancy Faber và Randall Faber","source_file":"VIBE_Piano_Pre_Grade_Repertoire_2B_50_Lessons.pdf","source_sha256":"a39a716dda54fde53549580c4e75889d4bca016be5810368d2f4fe21c108e997","source_context":"Trang giáo án VIBE 1\nVIBE ACADEMY · PIANO PRE GRADE · REPERTOIRE\nGiáo án 50 Lesson\ntheo Piano Adventures 2B\nPiano Adventures - Level 2B - Lesson Book\n(2nd Edition)\nNancy Faber và Randall Faber\nFaber Piano Adventures\nTên môn theo giáo trình\nRepertoire → Piano Adventures - Level 2B - Lesson Book (2nd Edition)\nVị trí theo yêu cầu: Piano → Pre Grade → môn Repertoire hiện có. Tên sách và ấn bản\nđược giữ trong dữ liệu nguồn; ID môn và lịch sử học tập cần được bảo toàn khi nhập.\nCách sử dụng\n• Bản phân bổ gồm 2 Lesson ôn Level 2A và 48 Lesson theo đúng thứ tự 10 Unit. Một\nLesson là một đơn vị nội dung, có thể cần nhiều buổi dạy.\n• Tiêu đề bài và trang tham chiếu lấy từ sách. Mục tiêu, hoạt động, bài luyện và ghi chú là\nphần VIBE biên soạn; không phải hướng dẫn dịch nguyên văn hoặc 50 Lesson do nhà xuất\nbản đánh số.\n• Level 2B là cấp độ riêng của bộ Piano Adventures. Việc xếp vào Pre Grade là yêu cầu\nnội bộ của VIBE; giáo viên cần kiểm tra kiến thức nền trước khi sử dụng.\n• Sách Lesson Book có cả bài biểu diễn, bài chuẩn bị và Challenge. Các nội dung này được\ngiữ cùng mạch sách trong môn được chỉ định.\n• Chưa áp dụng vào database trên máy Mac. Gói kèm theo chuẩn bị việc đổi tên và nhập\nnội dung vào đúng môn hiện có.\n\nTrang giáo án VIBE 2\nĐối chiếu nguồn và cấu trúc\nNguồn: 1) Lesson lv 2B.pdf - 76 trang scan. Đã đối chiếu hình ảnh toàn bộ trang, bảng\nProgress Chart ở PDF 4-5 và danh mục bài ở PDF 75. Phần nội dung học: trang in 4-71 =\nPDF 6-73.\nCác điểm cần giữ đúng\n• Chỉ cột Lesson trong Progress Chart thuộc quyển này. Những cột Theory, Technique,\nPerformance, Sightreading là dẫn chiếu sách khác, không được nhập thành nội dung mới\nkhi chưa có sách.\n• Lesson 28 và 29 cùng dẫn PDF 44/trang in 42: Lesson 28 học khung giới thiệu dấu lặng\nmóc đơn; Lesson 29 học bản Pumpkin Boogie kéo dài sang trang tiếp theo. Phạm vi khác\nnhau được ghi trong từng Lesson.\n• Sáu Lesson cuối là Challenge Section: mẫu năm ngón trưởng/thứ và chuỗi hợp âm. Giáo\nviên thêm hợp âm, hai tay, pedal khi học viên sẵn sàng; không biến thành yêu cầu chơi\ngam một quãng tám ở mọi giọng.\n• Trang chứng nhận PDF 74 không phải bài kiểm tra hoặc lệnh tự hoàn thành cấp độ. Bìa,\ngiới thiệu, bảng tiến độ, chứng nhận và danh mục không tạo Lesson riêng.\n• Các dấu tempo và số CD track được hiểu theo sách; không tạo ngưỡng đạt tự động hoặc\ngắn tệp âm thanh chưa được cung cấp.\nPhân bổ theo Unit\nMục\nTên theo sách\nLesson\nTrang in\nÔn 2A\nGet Ready for Take-off! (Level 2A Review)\n01-02\n4-5\n1\nThe Family of C''s\n03-06\n6-9\n2\nArpeggios\n07-08\n10-13\n3\nSixth (6th)\n09-12\n14-19\n4\nThe C Major Scale\n13-17\n20-27\n5\nThe G Major Scale\n18-23\n28-35\n6\nMore About the Damper Pedal\n24-27\n36-41\n7\nThe Eighth Rest\n28-29\n42-43\n8\nThe Dotted Quarter Note\n30-33\n44-49\n9\nThe Primary Chords\n34-38\n50-57\n10\nThe F Major Scale\n39-50\n58-71\n\nTrang giáo án VIBE 3\nBảng tra Lesson 01-17\nBài\nTên bài / hoạt động\nIn\nPDF\n01\nGet Ready for Take-off! - Rhythm / Reading\n4\n6\n02\nGet Ready for Take-off! - Theory / Symbols and Terms\n5\n7\n03\nThe Family of C''s / Moon Walker\n6\n8\n04\nCaptain Hook''s Rockin'' Party\n7\n9\n05\nAlmost Like a Dream\n8\n10\n06\nSounds from the Gumdrop Factory\n9\n11\n07\nCross-Hand Arpeggios - Major and Minor\n10-11\n12-13\n08\nSpanish Caballero\n12-13\n14-15\n09\nSixth (