oonlight\n56-57\n58-59\n39\nF Scale Warm-ups - Traveling Thumb\n58\n60\n40\nF Scale Warm-ups - One Hand - 8 Fingers / The Ultimate F Scale\nWarm-up\n59\n61\n41\nTurkish March (from The Ruins of Athens)\n60-61\n62-63\n42\nI, IV, and V7 Chords in the Key of F / Latin Sounds\n62\n64\n43\nAria (from the Peasant Cantata)\n63\n65\n44\nAuld Lang Syne\n64-65\n66-67\n45\nScale and Chord Adventures - C/Cm; G/Gm\n66\n68\n46\nScale and Chord Adventures - D/Dm; A/Am\n67\n69\n47\nScale and Chord Adventures - F/Fm; E/Em\n68\n70\n48\nScale and Chord Adventures - Db/Dbm; Ab/Abm\n69\n71\n49\nScale and Chord Adventures - Eb/Ebm; F#/F#m\n70\n72\n50\nScale and Chord Adventures - Bb/Bbm; B/Bm\n71\n73\nCác tên ghép hoặc chia phần dùng để tổ chức dạy; tên bài gốc được giữ trong tiêu đề. Dùng trang in để\ntra sách và trang PDF để tra tệp scan.","lessons":[{"number":1,"code":"PIANO-PRE-REP-2B-L01","title":"Get Ready for Take-off! - Rhythm / Reading","unit":0,"unit_title":"Ôn Level 2A","challenge":false,"source_pdf_pages":"6","source_printed_pages":"4","syllabus_pdf_page":6,"content_scope":"Phần Rhythm và Reading trong bài ôn Level 2A.","learning_objectives":"Ôn nhịp 2/4, 3/4, 4/4; đọc quãng 2, 3, 4, 5 và tên nốt trên hai khuông.","classroom_activities":"Điền số chỉ nhịp; gõ rồi đàn mẫu tiết tấu bằng hợp âm được cho; gọi tên quãng và các nốt trong từng ví dụ.","homework":"Ôn lại những mẫu tiết tấu hoặc quãng còn nhầm theo ghi chú của giáo viên.","teacher_notes":"Đây là kiểm tra kiến thức nền của sách, không phải Final Test. Bổ sung phần Level 2A còn thiếu trước khi tiến tiếp."},{"number":2,"code":"PIANO-PRE-REP-2B-L02","title":"Get Ready for Take-off! - Theory / Symbols and Terms","unit":0,"unit_title":"Ôn Level 2A","challenge":false,"source_pdf_pages":"7","source_printed_pages":"5","syllabus_pdf_page":6,"content_scope":"Phần Theory, Symbols and Terms trong bài ôn Level 2A.","learning_objectives":"Nhận diện mẫu năm ngón trưởng/thứ, âm chủ, âm át và các thuật ngữ đã học.","classroom_activities":"Điền tên nốt có dấu hóa, đánh dấu âm chủ/âm át, nhận diện mẫu và hợp âm trưởng/thứ rồi nối thuật ngữ với ý nghĩa.","homework":"Chơi lại các mẫu năm ngón được giao và giải thích các ký hiệu còn chưa nhớ.","teacher_notes":"Dùng kết quả để điều chỉnh phần ôn tập; không tự quy đổi Level 2B của Faber thành một Grade ABRSM."},{"number":3,"code":"PIANO-PRE-REP-2B-L03","title":"The Family of C''s / Moon Walker","unit":1,"unit_title":"The Family of C''s","challenge":false,"source_pdf_pages":"8","source_printed_pages":"6","syllabus_pdf_page":7,"content_scope":"Dòng kẻ phụ, các nốt C và toàn bài Moon Walker.","learning_objectives":"Tìm các nốt C ở nhiều âm vực; liên hệ dòng kẻ phụ với phím đàn.","classroom_activities":"Chỉ và đàn các nốt C bằng ngón được hướng dẫn; luyện chuyển tay nhẹ, dùng trọng lượng cánh tay rồi đàn bài.","homework":"Tìm nhanh các nốt C; luyện chuyển từ C này sang C khác và thử trên các nốt D theo sách.","teacher_notes":"Quan sát chuyển động nhấc tay và pedal; không giữ cánh tay căng khi đi xa."},{"number":4,"code":"PIANO-PRE-REP-2B-L04","title":"Captain Hook''s Rockin'' Party","unit":1,"unit_title":"The Family of C''s","challenge":false,"source_pdf_pages":"9","source_printed_pages":"7","syllabus_pdf_page":7,"content_scope":"Toàn bài và gợi ý biến đổi tiết tấu ở cuối trang.","learning_objectives":"Giữ nhịp rock, đọc các quãng và thể hiện dấu nhấn.","classroom_activities":"Gõ tiết tấu, tập từng tay rồi ghép; thực hiện phần lặp với tay phải cao hơn một quãng tám.","homework":"Ôn chỗ đổi vị trí và thử một tiết tấu khác cho các quãng 4 tay phải ở ô 9-10.","teacher_notes":"Giữ nhịp đều khi chuyển âm vực; sáng tạo là hoạt động mở rộng theo sách."},{"number":5,"code":"PIANO-PRE-REP-2B-L05","title":"Almost Like a Dream","unit":1,"unit_title":"The Family of C''s","challenge":false,"source_pdf_pages":"10","source_printed_pages":"8","syllabus_pdf_page":8,"content_scope":"Ôn fermata, hướng dẫn pedal và toàn bài.","learning_objectives":"Đọc giai điệu với sắc thái nhẹ, giữ âm bằng pedal và xử lý fermata.","classroom_activities":"Xác định tính trưởng/thứ ở đầu bài, chuẩn bị tay trái, đàn từng câu rồi nối với sắc thái và chậm dần cuối bài.","homework":"Ôn các điểm chuyển tay và nghe âm còn ngân; luyện kết bài nhẹ.","teacher_notes":"Sách yêu cầu giữ damper pedal suốt bài này; không áp dụng cách giữ đó cho mọi bài sau."},{"number":6,"code":"PIANO-PRE-REP-2B-L06","title":"Sounds from the Gumdrop Factory","unit":1,"unit_title":"The Family of C''s","challenge":false,"source_pdf_pages":"11","source_printed_pages":"9","syllabus_pdf_page":8,"content_scope":"Toàn bài, Tempo Check và Creative.","learning_objectives":"Giữ mẫu lặp tay trái ổn định khi tay phải thay đổi; kiểm soát tốc độ.","classroom_activities":"Luyện riêng mẫu lặp, ghép giai điệu; đối chiếu mốc máy đếm nhịp trong sách khi học viên đã vững.","homework":"Ôn đoạn chưa đều; thử tạo giai điệu tay phải bằng mẫu năm ngón C trên phần lặp tay trái.","teacher_notes":"Mốc tempo của sách là hướng dẫn luyện tập, không được dùng làm ngưỡng đạt tự động."},{"number":7,"code":"PIANO-PRE-REP-2B-L07","title":"Cross-Hand Arpeggios - Major and Minor","unit":2,"unit_title":"Arpeggios","challenge":false,"source_pdf_pages":"12-13","source_printed_pages":"10-11","syllabus_pdf_page":9,"content_scope":"Các arpeggio C, D, E, F trưởng/thứ và gợi ý G/Gm, A/Am.","learning_objectives":"Phân biệt hợp âm rải trưởng/thứ và chuyển tay qua nhau liền mạch.","classroom_activities":"Tập chậm các mẫu C, D, E, F; đọc dấu hóa và số ngón riêng của từng mẫu, chuẩn bị tay di chuyển trước khi chơi.","homework":"Ôn một nhóm mẫu còn khó; thử G/Gm hoặc A/Am khi giáo viên thấy phù hợp.","teacher_notes":"Không giữ nguyên một thế ngón cho mọi hợp âm; dùng số ngón in trong sách."},{"number":8,"code":"PIANO-PRE-REP-2B-L08","title":"Spanish Caballero","unit":2,"unit_title":"Arpeggios","challenge":false,"source_pdf_pages":"14-15","source_printed_pages":"12-13","syllabus_pdf_page":9,"content_scope":"Toàn bài, a tempo, chuyển âm vực và kết bài.","learning_objectives":"Ứng dụng arpeggio vắt tay, xử lý ritardando và trở lại tốc độ ban đầu.","classroom_activities":"Khoanh hai dấu a tempo, tập các điểm tay trái đi qua; ghép bài và thực hiện chỉ dẫn hạ âm vực ở phần sau.","homework":"Ôn từng điểm chuyển tay và luyện trở lại mạch nhịp sau chậm dần.","teacher_notes":"Phân biệt chỉ dẫn thấp hơn một quãng tám với hai quãng tám ở kết bài; không tăng tốc khi tay còn căng."},{"number":9,"code":"PIANO-PRE-REP-2B-L09","title":"Sixth (6th) / Sixth Hour","unit":3,"unit_title":"Sixth (6th)","challenge":false,"source_pdf_pages":"16","source_printed_pages":"14","syllabus_pdf_page":10,"content_scope":"Khái niệm quãng 6 và toàn bài Sixth Hour.","learning_objectives":"Nhận diện quãng 6 trên khuông và bàn phím; điều chỉnh ngón cái/ngón 5.","classroom_activities":"Điền tên nốt ở các hình phím, tìm quãng 6 lên/xuống; đàn bài và quan sát khoảng cách giữa ngón 1-2.","homework":"Luyện chuyển từ quãng 5 sang quãng 6; thử vị trí F-C theo gợi ý của sách.","teacher_notes":"Không ép độ giãn bàn tay; giáo viên điều chỉnh chuyển động theo tầm tay học viên."},{"number":10,"code":"PIANO-PRE-REP-2B-L10","title":"Boxcar Rumble","unit":3,"unit_title":"Sixth (6th)","challenge":false,"source_pdf_pages":"17","source_printed_pages":"15","syllabus_pdf_page":10,"content_scope":"Toàn bài và Technique Check.","learning_objectives":"Giữ mẫu đệm đều, đọc quãng 6 và tạo các mức sắc thái trong bài.","classroom_activities":"Luyện từng tay với cổ tay mềm; ghép bài chậm, cân bằng giai điệu với mẫu lặp.","homework":"Ôn các chỗ đổi quãng và chuyển sắc thái, giữ nhịp đến cuối câu.","teacher_notes":"Kiểm tra cổ tay linh hoạt trước khi nâng tốc độ."},{"number":11,"code":"PIANO-PRE-REP-2B-L11","title":"The Great Clock / Improvising Bell Sounds","unit":3,"unit_title":"Sixth (6th)","challenge":false,"source_pdf_pages":"18-19","source_printed_pages":"16-17","syllabus_pdf_page":11,"content_scope":"Toàn bài và hoạt động tạo tiếng chuông kết thúc.","learning_objectives":"Tạo âm chuông bằng trọng lượng tay, đọc quãng 6 và ứng tấu với nhóm nốt cho sẵn.","classroom_activities":"Đàn các câu chuông với tương phản f/p; chuẩn bị tay phải khi tay trái chơi ô 17-20 rồi ứng tấu đoạn cuối.","homework":"Ôn các câu chính và thử một cách kết thúc từ bốn nốt của sách.","teacher_notes":"Nghe độ ngân và giảm âm tự nhiên; giữ ứng tấu trong phạm vi hoạt động nguồn."},{"number":12,"code":"PIANO-PRE-REP-2B-L12","title":"1st and 2nd Endings / Shave and a Haircut","unit":3,"unit_title":"Sixth (6th)","challenge":false,"source_pdf_pages":"20-21","source_printed_pages":"18-19","syllabus_pdf_page":11,"content_scope":"Hai khung kết thúc, toàn bài và gợi ý đọc dấu lặng.","learning_objectives":"Theo đúng đường đi khi lặp với khung kết thúc 1 và 2.","classroom_activities":"Vạch đường đi trên bản nhạc, gõ tiết tấu, đàn các đoạn rồi ghép; gọi tên các dấu lặng tay trái ở dòng cuối.","homework":"Luyện chỗ quay lại và bỏ qua khung 1 ở lượt hai.","teacher_notes":"Phần Teacher Duet dành cho giáo viên, không biến thành bài bắt buộc của học viên."},{"number":13,"code":"PIANO-PRE-REP-2B-L13","title":"C Scale Warm-ups - Key of C Roadmap / Traveling Thumb","unit":4,"unit_title":"The C Major Scale","challenge":false,"source_pdf_pages":"22","source_printed_pages":"20","syllabus_pdf_page":12,"content_scope":"Phần giới thiệu gam C, bài khởi động 1-2.","learning_objectives":"Tìm âm chủ C, âm át G, âm dẫn B; hiểu chuyển ngón cái trong gam C.","classroom_activities":"Đọc sơ đồ gam, hát và đàn Roadmap; luyện Traveling Thumb từng tay rồi ngược chiều hai tay khi sẵn sàng.","homework":"Ôn chỗ luồn ngón và tìm nhanh ba âm chức năng trong giọng C.","teacher_notes":"Đây là phần 1 của mục C Scale Warm-ups; tên phần được tách để tổ chức Lesson."},{"number":14,"code":"PIANO-PRE-REP-2B-L14","title":"C Scale Warm-ups - One Hand - 8 Fingers / The Ultimate C Scale Warm-up","unit":4,"unit_title":"The C Major Scale","challenge":false,"source_pdf_pages":"23","source_printed_pages":"21","syllabus_pdf_page":12,"content_scope":"Bài khởi động 3-4 của gam C.","learning_objectives":"Chơi gam C liền tiếng với đúng số ngón và chuyển vị trí giữa các âm vực.","classroom_activities":"Luyện One Hand - 8 Fingers; thực hiện chuỗi gam ở các nốt C theo sơ đồ trong sách.","homework":"Ôn gam lên/xuống và điểm chuyển tay; giữ các nốt đều nhau.","teacher_notes":"Các tốc độ có chữ Optional là lựa chọn luyện tập, không phải ba mức thi."},{"number":15,"code":"PIANO-PRE-REP-2B-L15","title":"D.C. al Fine / Jumpin'' Jazz Cat","unit":4,"unit_title":"The C Major Scale","challenge":false,"source_pdf_pages":"24-25","source_printed_pages":"22-23","syllabus_pdf_page":13,"content_scope":"D.C. al Fine và toàn bài Jumpin'' Jazz Cat.","learning_objectives":"Chơi giai điệu trong giọng C và thực hiện đúng D.C. al Fine.","classroom_activities":"Đánh dấu Fine và D.C., tập chỗ đổi tay/nhảy vị trí; đàn theo đường đi đầy đủ của bản nhạc.","homework":"Ôn điểm quay lại đầu bài và chỗ kết thúc Fine.","teacher_notes":"Dẫn chiếu sang Classic Sonatina ở Performance Book là tài liệu ngoài tệp; không tự thêm Lesson từ sách chưa cung cấp."},{"number":16,"code":"PIANO-PRE-REP-2B-L16","title":"I and V7 Chords in the Key of C / Down by the Bay","unit":4,"unit_title":"The C Major Scale","challenge":false,"source_pdf_pages":"26-27","source_printed_pages":"24-25","syllabus_pdf_page":13,"content_scope":"Hợp âm I-V7 giọng C và toàn bài Down by the Bay.","learning_objectives":"Chuyển I sang V7 ba âm, nghe âm dẫn về âm chủ và ghép giai điệu với đệm.","classroom_activities":"So sánh V7 hai âm/ba âm, luyện chuyển hợp âm; tập từng câu và hai khung kết thúc của bài.","homework":"Ôn phần tay trái, có thể hát giai điệu trong lúc tự đệm như hoạt động sách.","teacher_notes":"Tách khó khăn về chuyển hợp âm khỏi khó khăn đọc giai điệu trước khi ghép."},{"number":17,"code":"PIANO-PRE-REP-2B-L17","title":"The Waltz Chord Pattern / The Ice Skaters","unit":4,"unit_title":"The C Major Scale","challenge":false,"source_pdf_pages":"28-29","source_printed_pages":"26-27","syllabus_pdf_page":14,"content_scope":"Mẫu đệm waltz, toàn bài và Reading Chord Symbols.","learning_objectives":"Chơi đệm waltz nhẹ, cân bằng giai điệu và đọc ký hiệu hợp âm.","classroom_activities":"Luyện mẫu I/V7, đàn bài theo câu; thực hiện lặp với tay phải cao hơn một quãng tám và D.C. al Fine.","homework":"Ôn phần đệm rồi chơi chuỗi hợp âm ở cuối trang bằng kiểu đệm waltz.","teacher_notes":"Giữ phần đệm nhẹ; dùng bản chuyển soạn của sách, không thay bằng tổng phổ gốc."},{"number":18,"code":"PIANO-PRE-REP-2B-L18","title":"G Scale Warm-ups - Key of G Roadmap / Traveling Thumb","unit":5,"unit_title":"The G Major Scale","challenge":false,"source_pdf_pages":"30","source_printed_pages":"28","syllabus_pdf_page":14,"content_scope":"Giới thiệu gam G và bài khởi động 1-2.","learning_objectives":"Tìm G, D, F-sharp là âm chủ, âm át, âm dẫn; vận dụng chuyển ngón trong gam G.","classroom_activities":"Hát/đàn Roadmap, luyện Traveling Thumb từng tay và ngược chiều theo sách.","homework":"Ôn dấu F-sharp và điểm luồn ngón, tìm các âm chức năng trong nhiều âm vực.","teacher_notes":"Giữ đúng dấu hóa khi chuyển từ giọng C sang G."},{"number":19,"code":"PIANO-PRE-REP-2B-L19","title":"G Scale Warm-ups - One Hand - 8 Fingers / The Ultimate G Scale Warm-up","unit":5,"unit_title":"The G Major Scale","challenge":false,"source_pdf_pages":"31","source_printed_pages":"29","syllabus_pdf_page":15,"content_scope":"Bài khởi động 3-4 của gam G.","learning_objectives":"Chơi gam G với số ngón ổn định và chuyển giữa các nốt G trên bàn phím.","classroom_activities":"Luyện gam lên/xuống; thực hiện sơ đồ sáu vị trí G khi tay đã thoải mái.","homework":"Ôn đoạn chuyển ngón còn gãy tiếng; tăng phạm vi dần theo chỉ dẫn giáo viên.","teacher_notes":"Mục tiêu là tiếng đàn đều và chuyển động tự nhiên; không bắt buộc tốc độ tối đa ghi tùy chọn."},{"number":20,"code":"PIANO-PRE-REP-2B-L20","title":"The Key Signature / Vive la France!","unit":5,"unit_title":"The G Major Scale","challenge":false,"source_pdf_pages":"32-33","source_printed_pages":"30-31","syllabus_pdf_page":15,"content_scope":"Hóa biểu giọng G và toàn bài Vive la France!.","learning_objectives":"Đọc hóa biểu một dấu thăng và duy trì F-sharp trong các dòng nhạc.","classroom_activities":"Đánh dấu hóa biểu từ ô 5, đàn từng câu với sắc thái; thử chuyển sang C theo hoạt động Discovery.","homework":"Ôn các chỗ đổi vị trí và tự kiểm tra các nốt F trong bài.","teacher_notes":"Chuyển giọng là hoạt động mở rộng sau khi bản ở giọng G đã ổn."},{"number":21,"code":"PIANO-PRE-REP-2B-L21","title":"I and V7 Chords in the Key of G / I''ve Got Peace Like a River","unit":5,"unit_title":"The G Major Scale","challenge":false,"source_pdf_pages":"34","source_printed_pages":"32","syllabus_pdf_page":16,"content_scope":"Hợp âm I-V7 giọng G và bài thứ nhất trong Two Spirituals.","learning_objectives":"Chuyển I/V7 ở giọng G và kết hợp giai điệu với đệm hợp âm.","classroom_activities":"Đọc âm dẫn về âm chủ trong mẫu hợp âm; tập đệm riêng, ghép từng câu của bài.","homework":"Ôn điểm đổi hợp âm và hát hoặc đọc giai điệu trên mạch nhịp đều.","teacher_notes":"Giữ phân biệt bài này với Deep River ở trang kế tiếp."},{"number":22,"code":"PIANO-PRE-REP-2B-L22","title":"Accidentals / Deep River","unit":5,"unit_title":"The G Major Scale","challenge":false,"source_pdf_pages":"35","source_printed_pages":"33","syllabus_pdf_page":16,"content_scope":"Dấu hóa bất thường và bài thứ hai trong Two Spirituals.","learning_objectives":"Phân biệt hóa biểu với dấu hóa trong bài; thể hiện giai điệu chậm có biểu cảm.","classroom_activities":"Tìm dấu hóa ở ô 6, luyện chuyển ngón và từng câu; ghép bài với chậm dần cuối câu.","homework":"Ôn câu có dấu hóa, nghe đường nét giai điệu thay vì chỉ tìm phím.","teacher_notes":"Đọc đúng bản chuyển soạn được gửi; giữ tiếng đệm cân bằng với giai điệu."},{"number":23,"code":"PIANO-PRE-REP-2B-L23","title":"Musical Form / Horse-Drawn Carriage","unit":5,"unit_title":"The G Major Scale","challenge":false,"source_pdf_pages":"36-37","source_printed_pages":"34-35","syllabus_pdf_page":17,"content_scope":"Hình thức AB, toàn bài và gợi ý chuyển giọng.","learning_objectives":"Nhận diện hai đoạn A/B và các chỉ dẫn lặp trong bài.","classroom_activities":"Ghi nhãn các đoạn, luyện mẫu tiết tấu và hai khung kết thúc; ghép bài theo đúng cấu trúc.","homework":"Ôn từng đoạn; thử chuỗi I-V7 ở G và C rồi chuyển giọng bài khi phù hợp.","teacher_notes":"Giữ nội dung phân tích hình thức gắn với bài biểu diễn, không tạo thêm môn mới."},{"number":24,"code":"PIANO-PRE-REP-2B-L24","title":"Three Rules for Pedaling / Pedal Warm-ups","unit":6,"unit_title":"More About the Damper Pedal","challenge":false,"source_pdf_pages":"38","source_printed_pages":"36","syllabus_pdf_page":17,"content_scope":"Giới thiệu damper pedal, ba quy tắc và ký hiệu pedal.","learning_objectives":"Đặt chân phải đúng, giữ gót và nhận diện ký hiệu nhấc/đạp lại pedal.","classroom_activities":"Giáo viên làm mẫu; học viên luyện chuyển động chân theo mẫu chữ rồi theo ký hiệu trên trang.","homework":"Ôn chuyển động chân ở tư thế thoải mái với đàn phù hợp.","teacher_notes":"Điều chỉnh ghế và hỗ trợ pedal theo tầm vóc; không ép trẻ với chân tới pedal bằng tư thế sai."},{"number":25,"code":"PIANO-PRE-REP-2B-L25","title":"Pedal Power","unit":6,"unit_title":"More About the Damper Pedal","challenge":false,"source_pdf_pages":"39","source_printed_pages":"37","syllabus_pdf_page":18,"content_scope":"Bốn gợi ý luyện tập và toàn bài.","learning_objectives":"Đạp pedal sau khi phát âm hợp âm để tạo tiếng nối mà không đục.","classroom_activities":"Tập tay phải không pedal, thêm chuyển động chân; chuẩn bị hợp âm kế trong phách 3-4 và nghe độ liền tiếng.","homework":"Ôn riêng một cặp chuyển hợp âm; thử hai tay khi giáo viên cho phép.","teacher_notes":"Tay trái ở hoạt động mở rộng chơi cùng hợp âm thấp hơn một quãng tám; Teacher Duet là phần giáo viên."},{"number":26,"code":"PIANO-PRE-REP-2B-L26","title":"New Note - Ledger Line A / Beach Party","unit":6,"unit_title":"More About the Damper Pedal","challenge":false,"source_pdf_pages":"40-41","source_printed_pages":"38-39","syllabus_pdf_page":18,"content_scope":"Nốt A dòng kẻ phụ, R.H. Warm-up và toàn bài.","learning_objectives":"Đọc nốt A dưới Middle C và chuyển các hợp âm C-Am-F-G với pedal.","classroom_activities":"Tìm C-B-A trên khuông, luyện phần khởi động tay phải, ghép bài và nghe từng lần đổi pedal.","homework":"Ôn chỗ chuyển hợp âm; có thể tạo một phiên bản riêng theo gợi ý Creative.","teacher_notes":"Giữ riêng phần bản nhạc chính với hoạt động tùy chọn chơi chậm bằng tay trái."},{"number":27,"code":"PIANO-PRE-REP-2B-L27","title":"More About Musical Form / Riding the Wind","unit":6,"unit_title":"More About the Damper Pedal","challenge":false,"source_pdf_pages":"42-43","source_printed_pages":"40-41","syllabus_pdf_page":19,"content_scope":"Hình thức ABA/A'' và toàn bài Riding the Wind.","learning_objectives":"Nhận diện phần trở lại A hoặc A biến đổi; nối câu bằng pedal và chuyển tay.","classroom_activities":"Ghi nhãn các đoạn, tập các điểm vắt tay, so sánh đoạn trở lại từ ô 25 với đoạn đầu.","homework":"Ôn hai chỗ nối đoạn và nghe sự liên tục của giai điệu.","teacher_notes":"Không mặc định mọi đoạn quay lại là A nguyên vẹn; cho học viên đối chiếu bản nhạc."},{"number":28,"code":"PIANO-PRE-REP-2B-L28","title":"The Eighth Rest","unit":7,"unit_title":"The Eighth Rest","challenge":false,"source_pdf_pages":"44","source_printed_pages":"42","syllabus_pdf_page":19,"content_scope":"Chỉ khung giới thiệu và mẫu gõ phía trên trang 42; chưa học toàn bài Pumpkin Boogie.","learning_objectives":"Hiểu nốt móc đơn và dấu lặng móc đơn đều chiếm nửa phách trong bài học này.","classroom_activities":"Đếm 1-and-2-and, gõ mẫu với giáo viên và giữ im lặng đủ nửa phách; thử các tốc độ sách đề nghị khi ổn định.","homework":"Gõ lại mẫu và đếm xuyên qua dấu lặng, không rút ngắn phách.","teacher_notes":"Chung trang nguồn với Lesson kế tiếp nhưng khác phạm vi nội dung; không phải bản scan trùng."},{"number":29,"code":"PIANO-PRE-REP-2B-L29","title":"Pumpkin Boogie","unit":7,"unit_title":"The Eighth Rest","challenge":false,"source_pdf_pages":"44-45","source_printed_pages":"42-43","syllabus_pdf_page":20,"content_scope":"Phần bản nhạc Pumpkin Boogie ở trang 42-43 và Boogie Improv Duet; phần giới thiệu đã học ở Lesson trước.","learning_objectives":"Ứng dụng dấu lặng móc đơn, giữ mẫu boogie và chuyển ngón đúng trong bài.","classroom_activities":"Nghe giáo viên làm mẫu ô 5-6; tập các chỗ nghỉ và đổi ngón, ghép bài rồi đổi vai trong ứng tấu duet nếu phù hợp.","homework":"Ôn ô nhịp có dấu lặng và vị trí chuyển nhanh; giữ nhịp đều khi ghép.","teacher_notes":"Thực hiện Creative theo mẫu năm ngón C minor trong sách; không tự thêm bài kiểm tra ứng tấu."},{"number":30,"code":"PIANO-PRE-REP-2B-L30","title":"The Dotted Quarter Note / Deck the Keys","unit":8,"unit_title":"The Dotted Quarter Note","challenge":false,"source_pdf_pages":"46-47","source_printed_pages":"44-45","syllabus_pdf_page":20,"content_scope":"So sánh tiết tấu, nốt đen chấm dôi và toàn bài Deck the Keys.","learning_objectives":"Cảm nhận nốt đen chấm dôi bằng cách liên hệ với nốt nối và chia nhỏ phách.","classroom_activities":"Gõ ba mẫu đầu trang, so sánh hai cách ghi cùng âm thanh; đàn bài và chú ý điểm vắt ngón/nhảy tay.","homework":"Ôn mẫu chấm dôi bằng gõ trước, sau đó ghép vào câu đàn.","teacher_notes":"Giữ nhịp bên trong nốt dài; không biến chấm dôi thành dừng chờ."},{"number":31,"code":"PIANO-PRE-REP-2B-L31","title":"This Is My Planet Earth","unit":8,"unit_title":"The Dotted Quarter Note","challenge":false,"source_pdf_pages":"48-49","source_printed_pages":"46-47","syllabus_pdf_page":21,"content_scope":"Toàn bài, G cross-hand arpeggio mở đầu và Discovery.","learning_objectives":"Kết hợp arpeggio vắt tay, tiết tấu chấm dôi và giai điệu có câu dài.","classroom_activities":"Tập mở đầu theo mẫu giáo viên, học phần giai điệu từng câu rồi ghép mở/kết; tìm mẫu tiết tấu chỉ định.","homework":"Ôn các điểm từ arpeggio vào giai điệu và chỗ đổi tay ở kết bài.","teacher_notes":"Giữ khác biệt tốc độ/tính chất giữa phần freely và phần giai điệu theo bản nhạc."},{"number":32,"code":"PIANO-PRE-REP-2B-L32","title":"What''s a Lead Sheet?","unit":8,"unit_title":"The Dotted Quarter Note","challenge":false,"source_pdf_pages":"50","source_printed_pages":"48","syllabus_pdf_page":21,"content_scope":"Ôn lead sheet Level 2A và chuẩn bị hợp âm Dm-C-Am.","learning_objectives":"Đọc giai điệu có ký hiệu hợp âm và phân biệt ký hiệu trưởng/thứ.","classroom_activities":"Gọi tên và đàn Dm-C-Am; tập chuyển thế tay, giáo viên và học viên thay nhau chơi giai điệu/đệm để chuẩn bị bài sau.","homework":"Ôn chuyển ba hợp âm và nhận diện chữ m trong ký hiệu.","teacher_notes":"Đây là phần chuẩn bị của sách; bài Hey, Ho, Nobody Home có Lesson riêng."},{"number":33,"code":"PIANO-PRE-REP-2B-L33","title":"Hey, Ho, Nobody Home","unit":8,"unit_title":"The Dotted Quarter Note","challenge":false,"source_pdf_pages":"51","source_printed_pages":"49","syllabus_pdf_page":22,"content_scope":"Lead sheet D minor và gợi ý tạo kết thúc.","learning_objectives":"Tự ghép đệm hợp âm từ lead sheet trong giọng D minor.","classroom_activities":"Tập giai điệu riêng, đệm riêng, rồi ghép; thực hiện pedal simile theo hướng dẫn.","homework":"Ôn nơi đổi hợp âm; chọn một ý tưởng kết bài được sách gợi ý khi phần chính đã vững.","teacher_notes":"Không chép thêm một bản đệm cố định ngoài nguồn; dùng ký hiệu hợp âm và lựa chọn giáo viên."},{"number":34,"code":"PIANO-PRE-REP-2B-L34","title":"The Primary Chords / Chord Jumps","unit":9,"unit_title":"The Primary Chords","challenge":false,"source_pdf_pages":"52","source_printed_pages":"50","syllabus_pdf_page":22,"content_scope":"I-IV-V7, Chord Drill và toàn bài Chord Jumps.","learning_objectives":"Nhận diện hợp âm chính trên bậc 1, 4, 5 và chuyển I-IV-V7-I ở C.","classroom_activities":"Nghe/nhìn giáo viên đàn và gọi tên hợp âm; viết tên nốt, tập chuyển vị trí trong Chord Jumps.","homework":"Ôn ba hợp âm với từng tay và gọi tên khi chuyển.","teacher_notes":"Đọc đúng dạng V7 trong ví dụ; không nhầm hợp âm thứ i với hợp âm trưởng I ở phần Challenge sau."},{"number":35,"code":"PIANO-PRE-REP-2B-L35","title":"Lazy Chord Blues","unit":9,"unit_title":"The Primary Chords","challenge":false,"source_pdf_pages":"53","source_printed_pages":"51","syllabus_pdf_page":23,"content_scope":"Đổi cách sắp nốt hợp âm IV, toàn bài và hai dấu hóa.","learning_objectives":"Giảm bước nhảy tay trái bằng thế hợp âm thuận tay; giữ màu sắc blues.","classroom_activities":"So sánh IV mới với Chord Jumps; ghi I/IV/V7 dưới ô nhịp, tìm hai dấu hóa và ghép bài.","homework":"Ôn thế IV và các chỗ chuyển hợp âm liên tục.","teacher_notes":"Giữ chức năng hợp âm khi đổi cách sắp nốt; không chuyển tất cả về thế gốc."},{"number":36,"code":"PIANO-PRE-REP-2B-L36","title":"New World Symphony Theme","unit":9,"unit_title":"The Primary Chords","challenge":false,"source_pdf_pages":"54-55","source_printed_pages":"52-53","syllabus_pdf_page":23,"content_scope":"Bản chuyển soạn, L.H. Warm-up và hai lựa chọn kết thúc.","learning_objectives":"Phối hợp hợp âm, pedal và tương phản tính chất giữa các phần.","classroom_activities":"Luyện tay trái ô 1-8, ghép hai tay với pedal; đọc các khung kết thúc và lựa chọn kết nhẹ hoặc trở lại phần đầu.","homework":"Ôn hai điểm nối đoạn và lựa chọn một cách kết theo sách.","teacher_notes":"Đây là bản chuyển soạn chủ đề của Dvorak trong sách, không phải yêu cầu chơi nguyên tác giao hưởng."},{"number":37,"code":"PIANO-PRE-REP-2B-L37","title":"I, IV, and V7 Chords in the Key of G / Duke of York Strut","unit":9,"unit_title":"The Primary Chords","challenge":false,"source_pdf_pages":"56-57","source_printed_pages":"54-55","syllabus_pdf_page":24,"content_scope":"Hợp âm chính giọng G, toàn bài và Discovery.","learning_objectives":"Chuyển I-IV-V7 ở G và giữ tiết tấu có năng lượng trong bài.","classroom_activities":"Gọi tên hợp âm khi đàn, nghe mẫu tiết tấu của giáo viên; luyện các điểm nhảy cao/thấp và tìm dấu hóa.","homework":"Ôn nhịp chấm dôi và hợp âm tay trái trước khi ghép trọn bài.","teacher_notes":"Giữ hóa biểu giọng G trong khi xử lý dấu hóa bất thường."},{"number":38,"code":"PIANO-PRE-REP-2B-L38","title":"Pianissimo / Canoeing in the Moonlight","unit":9,"unit_title":"The Primary Chords","challenge":false,"source_pdf_pages":"58-59","source_printed_pages":"56-57","syllabus_pdf_page":24,"content_scope":"pp, hợp âm rải và toàn bài cùng gợi ý sáng tạo.","learning_objectives":"Chơi hợp âm rải I-IV-V7 với pedal, kiểm soát sắc thái rất nhẹ.","classroom_activities":"Xác định giọng từ hóa biểu, tập đường rải từng đoạn và điểm đổi tay, luyện kết bài ở pp.","homework":"Ôn nối hợp âm rải; thử một câu ngắn bằng các hợp âm của sách nếu sẵn sàng.","teacher_notes":"Nghe độ trong của pedal và kiểm soát pp; không đồng nhất rất nhẹ với mất âm."},{"number":39,"code":"PIANO-PRE-REP-2B-L39","title":"F Scale Warm-ups - Traveling Thumb","unit":10,"unit_title":"The F Major Scale","challenge":false,"source_pdf_pages":"60","source_printed_pages":"58","syllabus_pdf_page":25,"content_scope":"Giới thiệu gam F, hóa biểu và bài khởi động 1.","learning_objectives":"Tìm âm chủ F, âm át C, âm dẫn E và đọc B-flat; điều chỉnh thế ngón gam F.","classroom_activities":"Gọi tên các âm chức năng, khoanh hóa biểu, luyện Traveling Thumb từng tay theo số ngón trên trang.","homework":"Ôn vị trí B-flat và điểm luồn ngón cái tay phải sau ngón 4.","teacher_notes":"Số ngón tay phải gam F khác mẫu C/G; không sao chép máy móc thế ngón đã học."},{"number":40,"code":"PIANO-PRE-REP-2B-L40","title":"F Scale Warm-ups - One Hand - 8 Fingers / The Ultimate F Scale Warm-up","unit":10,"unit_title":"The F Major Scale","challenge":false,"source_pdf_pages":"61","source_printed_pages":"59","syllabus_pdf_page":25,"content_scope":"Bài khởi động 2-3 của gam F.","learning_objectives":"Chơi gam F lên/xuống với đúng số ngón và di chuyển giữa các âm vực.","classroom_activities":"Luyện One Hand - 8 Fingers, sau đó đi qua các vị trí F theo sơ đồ khi học viên đã ổn định.","homework":"Ôn chỗ chuyển ngón và giữ đều tiếng ở nốt trắng/phím đen.","teacher_notes":"Mốc tempo tùy chọn trong sách chỉ hỗ trợ luyện; không tạo điểm đạt tự động."},{"number":41,"code":"PIANO-PRE-REP-2B-L41","title":"Turkish March (from The Ruins of Athens)","unit":10,"unit_title":"The F Major Scale","challenge":false,"source_pdf_pages":"62-63","source_printed_pages":"60-61","syllabus_pdf_page":26,"content_scope":"Bản chuyển soạn của Beethoven, Key Signature Warm-up và Discovery.","learning_objectives":"Đọc giọng F, thể hiện hành khúc và tìm dấu hóa ngoài hóa biểu.","classroom_activities":"Đánh dấu B-flat từ ô 4, tập mẫu nhấc tay theo hướng dẫn, ghép từng câu và tìm dấu hóa trong bài.","homework":"Ôn câu có chuyển ngón và giữ nhẹ các nốt sau phách nhấn.","teacher_notes":"Ghi đúng tên tác phẩm và bản chuyển soạn trong sách; không nhầm với một Turkish March khác."},{"number":42,"code":"PIANO-PRE-REP-2B-L42","title":"I, IV, and V7 Chords in the Key of F / Latin Sounds","unit":10,"unit_title":"The F Major Scale","challenge":false,"source_pdf_pages":"64","source_printed_pages":"62","syllabus_pdf_page":26,"content_scope":"Hợp âm chính giọng F, Latin Sounds và Reading Chord Symbols.","learning_objectives":"Chuyển hợp âm I-IV-V7 ở F và thực hiện tiết tấu, dấu nhấn của bài.","classroom_activities":"Đọc số ngón và gọi tên hợp âm, gõ tiết tấu rồi đàn; chơi chuỗi hợp âm cuối trang bằng từng tay.","homework":"Ôn chuyển IV/V7 và kiểm tra B-flat ở cả hai tay.","teacher_notes":"Giữ đúng mẫu tiết tấu ghi trong sách; không tự thay bằng một kiểu đệm Latin khác."},{"number":43,"code":"PIANO-PRE-REP-2B-L43","title":"Aria (from the Peasant Cantata)","unit":10,"unit_title":"The F Major Scale","challenge":false,"source_pdf_pages":"65","source_printed_pages":"63","syllabus_pdf_page":27,"content_scope":"Bản chuyển soạn của J.S. Bach và hoạt động tìm câu lặp.","learning_objectives":"Nhận diện câu nhạc bốn ô nhịp và thể hiện tiếng vang bằng sắc thái.","classroom_activities":"Đọc hóa biểu từng dòng, đàn câu mở đầu rồi tìm hai lần xuất hiện lại; so sánh âm lượng và câu kết.","homework":"Ôn các câu giống nhau với sắc thái phù hợp, giữ nhịp xuyên qua dấu lặng.","teacher_notes":"Dùng đúng bản chuyển soạn trong sách; chú ý độ nổi của giai điệu trên nền hợp âm."},{"number":44,"code":"PIANO-PRE-REP-2B-L44","title":"Auld Lang Syne","unit":10,"unit_title":"The F Major Scale","challenge":false,"source_pdf_pages":"66-67","source_printed_pages":"64-65","syllabus_pdf_page":27,"content_scope":"Toàn bài, nhận diện giọng và điền I-IV-V7.","learning_objectives":"Kết hợp nhịp chấm dôi, hợp âm chính và câu nhạc có biểu cảm.","classroom_activities":"Xác định giọng, điền chức năng hợp âm, luyện chỗ đổi ngón/giãn tay và các điểm kết câu.","homework":"Ôn các đoạn chuyển hợp âm, đàn trọn bài với nhịp chậm phù hợp.","teacher_notes":"Phần Teacher Duet thuộc giáo viên; không dùng trang chứng nhận kế sau Challenge làm lệnh tự hoàn thành cấp độ."},{"number":45,"code":"PIANO-PRE-REP-2B-L45","title":"Scale and Chord Adventures - C/Cm; G/Gm","unit":10,"unit_title":"The F Major Scale","challenge":true,"source_pdf_pages":"68","source_printed_pages":"66","syllabus_pdf_page":28,"content_scope":"Challenge Section, nhóm mẫu C/Cm; G/Gm trên trang 66.","learning_objectives":"Luyện mẫu năm ngón trưởng/thứ và chuỗi hợp âm theo nhóm C/Cm; G/Gm.","classroom_activities":"Đối chiếu màu sắc trưởng/thứ và đọc chuỗi i-I-IV-I-V7-I. Tập từng tay; thêm hợp âm, hai tay và pedal khi học viên đã sẵn sàng.","homework":"Ôn nhóm đang học; ghi lại mẫu còn nhầm để giáo viên chọn phần củng cố.","teacher_notes":"Phần Challenge được dạy theo mức sẵn sàng. Đây là mẫu năm ngón, không phải bộ gam một quãng tám cho mọi giọng; pedal ở mẫu đầu được ghi tùy chọn."},{"number":46,"code":"PIANO-PRE-REP-2B-L46","title":"Scale and Chord Adventures - D/Dm; A/Am","unit":10,"unit_title":"The F Major Scale","challenge":true,"source_pdf_pages":"69","source_printed_pages":"67","syllabus_pdf_page":28,"content_scope":"Challenge Section, nhóm mẫu D/Dm; A/Am trên trang 67.","learning_objectives":"Luyện mẫu năm ngón trưởng/thứ và chuỗi hợp âm theo nhóm D/Dm; A/Am.","classroom_activities":"Kiểm tra dấu thăng khi chuyển giữa mẫu năm ngón trưởng và thứ. Tập từng tay; thêm hợp âm, hai tay và pedal khi học viên đã sẵn sàng.","homework":"Ôn nhóm đang học; ghi lại mẫu còn nhầm để giáo viên chọn phần củng cố.","teacher_notes":"Phần Challenge được dạy theo mức sẵn sàng. Đây là mẫu năm ngón, không phải bộ gam một quãng tám cho mọi giọng; pedal ở mẫu đầu được ghi tùy chọn."},{"number":47,"code":"PIANO-PRE-REP-2B-L47","title":"Scale and Chord Adventures - F/Fm; E/Em","unit":10,"unit_title":"The F Major Scale","challenge":true,"source_pdf_pages":"70","source_printed_pages":"68","syllabus_pdf_page":29,"content_scope":"Challenge Section, nhóm mẫu F/Fm; E/Em trên trang 68.","learning_objectives":"Luyện mẫu năm ngón trưởng/thứ và chuỗi hợp âm theo nhóm F/Fm; E/Em.","classroom_activities":"Theo dõi thay đổi dấu hóa và thế ngón ở các mẫu F và E. Tập từng tay; thêm hợp âm, hai tay và pedal khi học viên đã sẵn sàng.","homework":"Ôn nhóm đang học; ghi lại mẫu còn nhầm để giáo viên chọn phần củng cố.","teacher_notes":"Phần Challenge được dạy theo mức sẵn sàng. Đây là mẫu năm ngón, không phải bộ gam một quãng tám cho mọi giọng; pedal ở mẫu đầu được ghi tùy chọn."},{"number":48,"code":"PIANO-PRE-REP-2B-L48","title":"Scale and Chord Adventures - Db/Dbm; Ab/Abm","unit":10,"unit_title":"The F Major Scale","challenge":true,"source_pdf_pages":"71","source_printed_pages":"69","syllabus_pdf_page":29,"content_scope":"Challenge Section, nhóm mẫu Db/Dbm; Ab/Abm trên trang 69.","learning_objectives":"Luyện mẫu năm ngón trưởng/thứ và chuỗi hợp âm theo nhóm Db/Dbm; Ab/Abm.","classroom_activities":"Đọc kỹ các dấu giáng và dạng ký âm được dùng trong bản sách. Tập từng tay; thêm hợp âm, hai tay và pedal khi học viên đã sẵn sàng.","homework":"Ôn nhóm đang học; ghi lại mẫu còn nhầm để giáo viên chọn phần củng cố.","teacher_notes":"Phần Challenge được dạy theo mức sẵn sàng. Đây là mẫu năm ngón, không phải bộ gam một quãng tám cho mọi giọng; pedal ở mẫu đầu được ghi tùy chọn."},{"number":49,"code":"PIANO-PRE-REP-2B-L49","title":"Scale and Chord Adventures - Eb/Ebm; F#/F#m","unit":10,"unit_title":"The F Major Scale","challenge":true,"source_pdf_pages":"72","source_printed_pages":"70","syllabus_pdf_page":30,"content_scope":"Challenge Section, nhóm mẫu Eb/Ebm; F#/F#m trên trang 70.","learning_objectives":"Luyện mẫu năm ngón trưởng/thứ và chuỗi hợp âm theo nhóm Eb/Ebm; F#/F#m.","classroom_activities":"Phân biệt nhóm dấu giáng và nhóm dấu thăng; giữ thế tay ổn định. Tập từng tay; thêm hợp âm, hai tay và pedal khi học viên đã sẵn sàng.","homework":"Ôn nhóm đang học; ghi lại mẫu còn nhầm để giáo viên chọn phần củng cố.","teacher_notes":"Phần Challenge được dạy theo mức sẵn sàng. Đây là mẫu năm ngón, không phải bộ gam một quãng tám cho mọi giọng; pedal ở mẫu đầu được ghi tùy chọn."},{"number":50,"code":"PIANO-PRE-REP-2B-L50","title":"Scale and Chord Adventures - Bb/Bbm; B/Bm","unit":10,"unit_title":"The F Major Scale","challenge":true,"source_pdf_pages":"73","source_printed_pages":"71","syllabus_pdf_page":30,"content_scope":"Challenge Section, nhóm mẫu Bb/Bbm; B/Bm trên trang 71.","learning_objectives":"Luyện mẫu năm ngón trưởng/thứ và chuỗi hợp âm theo nhóm Bb/Bbm; B/Bm.","classroom_activities":"So sánh hai nhóm mẫu cuối, củng cố chuyển trưởng/thứ và hợp âm. Tập từng tay; thêm hợp âm, hai tay và pedal khi học viên đã sẵn sàng.","homework":"Ôn nhóm đang học; ghi lại mẫu còn nhầm để giáo viên chọn phần củng cố.","teacher_notes":"Phần Challenge được dạy theo mức sẵn sàng. Đây là mẫu năm ngón, không phải bộ gam một quãng tám cho mọi giọng; pedal ở mẫu đầu được ghi tùy chọn."}]}]}'::jsonb);
-- Targeted curriculum replacement; requires existing Book B syllabus schema.
set local lock_timeout='5s';
set local statement_timeout='90s';
select pg_advisory_xact_lock(hashtextextended('vibe:piano-pre-grade-repertoire',0));
lock table curriculums,curriculum_levels,curriculum_subjects,curriculum_subject_components,curriculum_component_items,curriculum_lesson_syllabi in share row exclusive mode;
lock table student_curriculum_enrollments,student_level_progress,student_subject_progress,student_component_progress,student_component_item_progress in share mode;
alter table curriculum_lesson_syllabi add column if not exists content_scope text not null default '';
alter table curriculum_lesson_syllabi add column if not exists syllabus_pdf_page integer check(syllabus_pdf_page between 1 and 999);
create temp table rep_changes(kind text,id uuid) on commit drop;
do $rep$
declare plan jsonb:=(select payload from rep_plan); b jsonb; v jsonb; lid uuid; oldid uuid; sid uuid; cid uuid; iid uuid; k int; t text; digest text; before_progress jsonb:='{}'; after_progress jsonb:='{}'; other_before jsonb; other_after jsonb; old_components jsonb; old_items jsonb;
begin
 select l.id into strict lid from curriculums p join curriculum_levels l on l.curriculum_id=p.id where p.code='PIANO' and l.code='PRE' and l.name='Pre Grade';
 select id into strict oldid from curriculum_subjects where level_id=lid and code='REPERTOIRE';
 if jsonb_array_length(plan->'books')<>2 then raise exception 'REPERTOIRE_NEEDS_TWO_BOOKS'; end if;
 select jsonb_agg(to_jsonb(s) order by id) into other_before from curriculum_subjects s where id<>oldid and not(level_id=lid and code in('REPERTOIRE_2A','REPERTOIRE_2B'));
 select jsonb_agg(to_jsonb(c) order by id) into old_components from curriculum_subject_components c where subject_id=oldid;
 select jsonb_agg(to_jsonb(i) order by i.id) into old_items from curriculum_component_items i join curriculum_subject_components c on c.id=i.component_id where c.subject_id=oldid;
 foreach t in array array['student_curriculum_enrollments','student_level_progress','student_subject_progress','student_component_progress','student_component_item_progress'] loop
  execute format('select md5(coalesce(jsonb_agg(to_jsonb(t) order by id)::text,''[]'')) from %I t',t) into digest;
  before_progress:=before_progress||jsonb_build_object(t,digest);
 end loop;
 for b in select value from jsonb_array_elements(plan->'books') loop
  if b->>'subject_code' not in('REPERTOIRE_2A','REPERTOIRE_2B') or jsonb_array_length(b->'lessons')<>50 then raise exception 'REPERTOIRE_BOOK_PLAN_INVALID'; end if;
  select id into sid from curriculum_subjects where level_id=lid and code=b->>'subject_code';
  if sid is null then
   select coalesce(max(sort_order),0)+1 into k from curriculum_subjects where level_id=lid;
   insert into curriculum_subjects(level_id,code,name,family_code,sort_order,status,is_required,completion_rule) values(lid,b->>'subject_code',b->>'subject_name','REPERTOIRE',k,'ACTIVE',false,'MANUAL') returning id into sid;
   insert into rep_changes values('subject',sid);
  elsif not exists(select 1 from curriculum_subjects where id=sid and name=b->>'subject_name' and family_code='REPERTOIRE' and status='ACTIVE' and not is_required and completion_rule='MANUAL') then raise exception 'REPERTOIRE_EXISTING_SUBJECT_CONFLICT'; end if;
  for v in select distinct on ((value->>'unit')::int) value from jsonb_array_elements(b->'lessons') order by (value->>'unit')::int loop
   select id into cid from curriculum_subject_components where subject_id=sid and code='REP-'||(b->>'book')||'-U'||lpad(v->>'unit',2,'0');
   if cid is null then
    insert into curriculum_subject_components(subject_id,code,name,sort_order,is_required,status,completion_rule) values(sid,'REP-'||(b->>'book')||'-U'||lpad(v->>'unit',2,'0'),case when (v->>'unit')::int=0 then v->>'unit_title' else 'Unit '||(v->>'unit')||' — '||(v->>'unit_title') end,(v->>'unit')::int,false,'ACTIVE','DIRECT_ASSESSMENT') returning id into cid;
    insert into rep_changes values('unit',cid);
   end if;
   if not exists(select 1 from curriculum_subject_components where id=cid and status='ACTIVE' and not is_required and completion_rule='DIRECT_ASSESSMENT' and sort_order=(v->>'unit')::int and name=case when (v->>'unit')::int=0 then v->>'unit_title' else 'Unit '||(v->>'unit')||' — '||(v->>'unit_title') end) then raise exception 'REPERTOIRE_EXISTING_UNIT_CONFLICT'; end if;
  end loop;
  for v in select value from jsonb_array_elements(b->'lessons') loop
   select id into cid from curriculum_subject_components where subject_id=sid and code='REP-'||(b->>'book')||'-U'||lpad(v->>'unit',2,'0');
   select i.id into iid from curriculum_component_items i join curriculum_subject_components c on c.id=i.component_id where c.subject_id=sid and i.code=v->>'code';
   if iid is null then
    insert into curriculum_component_items(component_id,code,name,sort_order,status,is_required) values(cid,v->>'code',v->>'title',(v->>'number')::int,'ACTIVE',false) returning id into iid;
    insert into rep_changes values('lesson',iid);
   end if;
   if not exists(select 1 from curriculum_component_items where id=iid and component_id=cid and name=v->>'title' and sort_order=(v->>'number')::int and status='ACTIVE' and not is_required) then raise exception 'REPERTOIRE_EXISTING_LESSON_CONFLICT'; end if;
   insert into curriculum_lesson_syllabi(item_id,source_book,source_authors,source_sha256,unit_title,source_pdf_pages,source_printed_pages,learning_objectives,classroom_activities,homework,teacher_notes,source_context,content_scope,syllabus_pdf_page)
   values(iid,b->>'subject_name',b->>'source_authors',b->>'source_sha256',v->>'unit_title',v->>'source_pdf_pages',v->>'source_printed_pages',v->>'learning_objectives',v->>'classroom_activities',v->>'homework',v->>'teacher_notes',case when (v->>'number')::int=1 then b->>'source_context' else '' end,v->>'content_scope',(v->>'syllabus_pdf_page')::int) on conflict(item_id) do nothing;
   if found then insert into rep_changes values('syllabus',iid); end if;
   if not exists(select 1 from curriculum_lesson_syllabi g where g.item_id=iid and (g.source_book,g.source_authors,g.source_sha256,g.unit_title,g.source_pdf_pages,g.source_printed_pages,g.learning_objectives,g.classroom_activities,g.homework,g.teacher_notes,g.content_scope,g.syllabus_pdf_page,g.source_context) is not distinct from (b->>'subject_name',b->>'source_authors',b->>'source_sha256',v->>'unit_title',v->>'source_pdf_pages',v->>'source_printed_pages',v->>'learning_objectives',v->>'classroom_activities',v->>'homework',v->>'teacher_notes',v->>'content_scope',(v->>'syllabus_pdf_page')::int,case when (v->>'number')::int=1 then b->>'source_context' else '' end)) then raise exception 'REPERTOIRE_EXISTING_SYLLABUS_CONFLICT'; end if;
  end loop;
  if (select count(*) from curriculum_component_items i join curriculum_subject_components c on c.id=i.component_id where c.subject_id=sid)<>50 or (select count(*) from curriculum_subject_components where subject_id=sid)<>(select count(distinct (value->>'unit')::int) from jsonb_array_elements(b->'lessons')) then raise exception 'REPERTOIRE_EXTRA_CONTENT_CONFLICT'; end if;
 end loop;
 -- Preserve all child rows and historical links of the old subject, including its required flags/rules.
 update curriculum_subjects set status='INACTIVE' where id=oldid and status='ACTIVE';
 if found then insert into rep_changes values('retired_subject',oldid); end if;
 foreach t in array array['student_curriculum_enrollments','student_level_progress','student_subject_progress','student_component_progress','student_component_item_progress'] loop
  execute format('select md5(coalesce(jsonb_agg(to_jsonb(t) order by id)::text,''[]'')) from %I t',t) into digest;
  after_progress:=after_progress||jsonb_build_object(t,digest);
 end loop;
 if before_progress<>after_progress then raise exception 'REPERTOIRE_PROGRESS_CHANGED'; end if;
 select jsonb_agg(to_jsonb(s) order by id) into other_after from curriculum_subjects s where id<>oldid and not(level_id=lid and code in('REPERTOIRE_2A','REPERTOIRE_2B'));
 if other_after is distinct from other_before or old_components is distinct from (select jsonb_agg(to_jsonb(c) order by id) from curriculum_subject_components c where subject_id=oldid) or old_items is distinct from (select jsonb_agg(to_jsonb(i) order by i.id) from curriculum_component_items i join curriculum_subject_components c on c.id=i.component_id where c.subject_id=oldid) then raise exception 'REPERTOIRE_UNRELATED_OR_OLD_CONTENT_CHANGED'; end if;
end $rep$;
select jsonb_build_object('changes',(select coalesce(jsonb_agg(to_jsonb(a)),'[]') from rep_changes a),'progress_unchanged',true,'old_content_preserved',true,'other_subjects_unchanged',true);
